BEGIN
 FOR item IN SELECT value FROM jsonb_array_elements($payload$[{"slug":"how-state-works","index":0,"title":"الدولة والسيادة","model":"institutions","activity":{"kind":"case","title":"هل هذه دولة أم مؤسسة؟","story":"مدينة صغيرة فيها سكان وأرض وسلطة بلدية، لكنها جزء من دولة قائمة.","question":"ما الذي ينقصها لتوصف دولة مستقلة؟","choices":["ممارسة سيادة الدولة والاعتراف بعلاقاتها الدولية وفق القانون","وجود مبنى البلدية فقط","وجود سوق تجاري كبير"],"explain":"البلدية تدير شؤونًا محلية، أما الدولة فتضم إقليمًا وسكانًا وسلطة وسيادة. لا تكفي المباني أو الأسواق وحدها.","correctIndex":0},"oldBody":"حين تتفاوض دولتان على اتفاقية تمارس كل منهما صلاحياتها الخارجية عبر مؤسساتها المخولة.\n\nوالآن تخيّل الموقف التالي: مدينة صغيرة فيها سكان وأرض وسلطة بلدية، لكنها جزء من دولة قائمة.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"حين تتفاوض دولتان على اتفاقية تمارس كل منهما صلاحياتها الخارجية عبر مؤسساتها المخولة.\n\nوالآن تخيّل الموقف التالي: مدينة صغيرة فيها سكان وأرض وسلطة بلدية، لكنها جزء من دولة قائمة.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال مشروح خطوة بخطوة: مدينة صغيرة فيها سكان وأرض وسلطة بلدية، لكنها جزء من دولة قائمة. نبدأ بتحديد السؤال: ما الذي ينقصها لتوصف دولة مستقلة؟ ننظر في الخيارات، ثم نبحث عن المعلومة التي يثبتها الواقع أو القانون. في هذا الموقف الإجابة الأدق هي «ممارسة سيادة الدولة والاعتراف بعلاقاتها الدولية وفق القانون». والسبب: البلدية تدير شؤونًا محلية، أما الدولة فتضم إقليمًا وسكانًا وسلطة وسيادة. لا تكفي المباني أو الأسواق وحدها.","questions":[{"kind":"choice","prompt":"في حالة «هل هذه دولة أم مؤسسة؟»: ما الذي ينقصها لتوصف دولة مستقلة؟","target":"مدينة صغيرة فيها سكان وأرض وسلطة بلدية، لكنها جزء من دولة قائمة.","options":["ممارسة سيادة الدولة والاعتراف بعلاقاتها الدولية وفق القانون","وجود مبنى البلدية فقط","وجود سوق تجاري كبير","لا علاقة لتلك الخيارات بفهم الموقف"],"answerIndex":0,"explanation":"البلدية تدير شؤونًا محلية، أما الدولة فتضم إقليمًا وسكانًا وسلطة وسيادة. لا تكفي المباني أو الأسواق وحدها."},{"kind":"choice","prompt":"ما الذي تثبته صلاحية البلدية بجمع النفايات؟","target":"مدينة صغيرة فيها سكان وأرض وسلطة بلدية، لكنها جزء من دولة قائمة.","options":["تقوم بعمل إداري محلي ولا يكفي ذلك لإثبات سيادة دولة","تمنح البلدية سيادة مستقلة على الإقليم","تجعل البلدية عضوًا في جميع المنظمات الدولية","تلغي دور مؤسسات الدولة الأخرى"],"answerIndex":0,"explanation":"البلدية تدير شؤونًا محلية، أما الدولة فتضم إقليمًا وسكانًا وسلطة وسيادة. لا تكفي المباني أو الأسواق وحدها."}]},{"slug":"how-state-works","index":1,"title":"الشعب والمواطنة","model":"institutions","activity":{"kind":"case","title":"إقامة أم مواطنة؟","story":"تقيم سلمى في بلد منذ خمس سنوات بإقامة قانونية لكنها لا تحمل جنسيته.","question":"ما المعلومة التي تحتاجها لتعرف هل تملك حق التصويت الوطني؟","choices":["عدد الأصدقاء الذين تعرفهم","قواعد الجنسية والانتخابات في هذا البلد","نوع العمل الذي تؤديه"],"explain":"حقوق التصويت ترتبط بالقانون والصفة الانتخابية ولا تُستنتج تلقائيًا من طول الإقامة.","correctIndex":1},"oldBody":"قد يقيم شخص لسنوات في بلد دون أن يحمل جنسيته؛ إقامته لا تعطيه تلقائيًا جميع حقوق الجنسية.\n\nوالآن تخيّل الموقف التالي: تقيم سلمى في بلد منذ خمس سنوات بإقامة قانونية لكنها لا تحمل جنسيته.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"قد يقيم شخص لسنوات في بلد دون أن يحمل جنسيته؛ إقامته لا تعطيه تلقائيًا جميع حقوق الجنسية.\n\nوالآن تخيّل الموقف التالي: تقيم سلمى في بلد منذ خمس سنوات بإقامة قانونية لكنها لا تحمل جنسيته.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال مشروح خطوة بخطوة: تقيم سلمى في بلد منذ خمس سنوات بإقامة قانونية لكنها لا تحمل جنسيته. نبدأ بتحديد السؤال: ما المعلومة التي تحتاجها لتعرف هل تملك حق التصويت الوطني؟ ننظر في الخيارات، ثم نبحث عن المعلومة التي يثبتها الواقع أو القانون. في هذا الموقف الإجابة الأدق هي «قواعد الجنسية والانتخابات في هذا البلد». والسبب: حقوق التصويت ترتبط بالقانون والصفة الانتخابية ولا تُستنتج تلقائيًا من طول الإقامة.","questions":[{"kind":"choice","prompt":"في حالة «إقامة أم مواطنة؟»: ما المعلومة التي تحتاجها لتعرف هل تملك حق التصويت الوطني؟","target":"تقيم سلمى في بلد منذ خمس سنوات بإقامة قانونية لكنها لا تحمل جنسيته.","options":["عدد الأصدقاء الذين تعرفهم","قواعد الجنسية والانتخابات في هذا البلد","نوع العمل الذي تؤديه","لا علاقة لتلك الخيارات بفهم الموقف"],"answerIndex":1,"explanation":"حقوق التصويت ترتبط بالقانون والصفة الانتخابية ولا تُستنتج تلقائيًا من طول الإقامة."},{"kind":"choice","prompt":"عندما نريد التأكد من أهلية مقيم للتصويت، ما المرجع المناسب؟","target":"تقيم سلمى في بلد منذ خمس سنوات بإقامة قانونية لكنها لا تحمل جنسيته.","options":["القانون المنظم للجنسية والانتخابات في البلد","مدة الإقامة وحدها في كل الدول","وجود عقد عمل ساري بوصفه كافيًا للتصويت","عدد سنوات الدراسة دون نص قانوني"],"answerIndex":0,"explanation":"حقوق التصويت ترتبط بالقانون والصفة الانتخابية ولا تُستنتج تلقائيًا من طول الإقامة."}]},{"slug":"how-state-works","index":2,"title":"الدستور والقواعد العليا","model":"institutions","activity":{"kind":"steps","title":"من يحسم خلاف الصلاحيات؟","story":"وزارة ومجلس محلي يختلفان حول من يملك إصدار قرار. كيف تبحث عن الإجابة؟","steps":["ارجع إلى النص الدستوري أو القانوني","حدد اختصاص كل جهة وفق النص","افحص جهة تفسير النص أو الفصل في النزاع"],"explain":"لا تبدأ بترجيح جهة لأن اسمها أكبر؛ اقرأ سند الاختصاص أولًا."},"oldBody":"إذا وقع خلاف حول صلاحية مؤسسة فقد تُراجع النصوص الدستورية لتحديد صاحب الاختصاص.\n\nوالآن تخيّل الموقف التالي: وزارة ومجلس محلي يختلفان حول من يملك إصدار قرار. كيف تبحث عن الإجابة؟\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"إذا وقع خلاف حول صلاحية مؤسسة فقد تُراجع النصوص الدستورية لتحديد صاحب الاختصاص.\n\nوالآن تخيّل الموقف التالي: وزارة ومجلس محلي يختلفان حول من يملك إصدار قرار. كيف تبحث عن الإجابة؟\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال محلول: وزارة ومجلس محلي يختلفان حول من يملك إصدار قرار. كيف تبحث عن الإجابة؟ الترتيب هنا هو: ارجع إلى النص الدستوري أو القانوني ← حدد اختصاص كل جهة وفق النص ← افحص جهة تفسير النص أو الفصل في النزاع. افهم ما تحتاجه كل خطوة من سابقتها، ولماذا يختلف القرار النهائي لو بدأنا بالنتيجة بدل دراسة المعطيات. لا تبدأ بترجيح جهة لأن اسمها أكبر؛ اقرأ سند الاختصاص أولًا.","questions":[{"kind":"choice","prompt":"أي إجراء يسبق بقية الإجراءات في هذا المثال؟","target":"وزارة ومجلس محلي يختلفان حول من يملك إصدار قرار. كيف تبحث عن الإجابة؟","options":["ارجع إلى النص الدستوري أو القانوني","حدد اختصاص كل جهة وفق النص","افحص جهة تفسير النص أو الفصل في النزاع","ليس من الضروري ترتيب الإجراءات مطلقًا"],"answerIndex":0,"explanation":"الترتيب في هذا المثال: ارجع إلى النص الدستوري أو القانوني ← حدد اختصاص كل جهة وفق النص ← افحص جهة تفسير النص أو الفصل في النزاع. لا تبدأ بترجيح جهة لأن اسمها أكبر؛ اقرأ سند الاختصاص أولًا."},{"kind":"choice","prompt":"ما الإجراء الذي يلي «ارجع إلى النص الدستوري أو القانوني» مباشرة؟","target":"وزارة ومجلس محلي يختلفان حول من يملك إصدار قرار. كيف تبحث عن الإجابة؟","options":["ارجع إلى النص الدستوري أو القانوني","حدد اختصاص كل جهة وفق النص","افحص جهة تفسير النص أو الفصل في النزاع","ليس من الضروري ترتيب الإجراءات مطلقًا"],"answerIndex":1,"explanation":"الترتيب في هذا المثال: ارجع إلى النص الدستوري أو القانوني ← حدد اختصاص كل جهة وفق النص ← افحص جهة تفسير النص أو الفصل في النزاع. لا تبدأ بترجيح جهة لأن اسمها أكبر؛ اقرأ سند الاختصاص أولًا."},{"kind":"choice","prompt":"ما الإجراء الأخير في هذا التسلسل؟","target":"وزارة ومجلس محلي يختلفان حول من يملك إصدار قرار. كيف تبحث عن الإجابة؟","options":["ارجع إلى النص الدستوري أو القانوني","حدد اختصاص كل جهة وفق النص","افحص جهة تفسير النص أو الفصل في النزاع","ليس من الضروري ترتيب الإجراءات مطلقًا"],"answerIndex":2,"explanation":"الترتيب في هذا المثال: ارجع إلى النص الدستوري أو القانوني ← حدد اختصاص كل جهة وفق النص ← افحص جهة تفسير النص أو الفصل في النزاع. لا تبدأ بترجيح جهة لأن اسمها أكبر؛ اقرأ سند الاختصاص أولًا."}]},{"slug":"how-state-works","index":3,"title":"الفصل بين السلطات","model":"institutions","activity":{"kind":"paths","title":"ثلاث سلطات في مشروع واحد","story":"مشروع قانون عن المدارس: مؤسسة تقترح، أخرى تقر، وثالثة تنظر في نزاع محتمل.","question":"استعرض وظيفة كل جهة في هذا المشروع.","choices":[["البرلمان","يناقش القانون ويصوت وفق الإجراءات."],["الإدارة","تنفذ القانون وتدير الخدمة وفق الميزانية."],["القضاء","يفصل في النزاعات القانونية عند وصولها إليه."]],"explain":"توزيع الوظائف يمنع خلط إصدار القاعدة بتنفيذها والفصل في النزاع، مع اختلاف التفاصيل بين الدساتير."},"oldBody":"حين تُقر مؤسسة تشريعية قانونًا وتطبقه الإدارة ويفصل القضاء في النزاع تظهر وظائف مختلفة.\n\nوالآن تخيّل الموقف التالي: مشروع قانون عن المدارس: مؤسسة تقترح، أخرى تقر، وثالثة تنظر في نزاع محتمل.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"حين تُقر مؤسسة تشريعية قانونًا وتطبقه الإدارة ويفصل القضاء في النزاع تظهر وظائف مختلفة.\n\nوالآن تخيّل الموقف التالي: مشروع قانون عن المدارس: مؤسسة تقترح، أخرى تقر، وثالثة تنظر في نزاع محتمل.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال مشروح للمقارنة: مشروع قانون عن المدارس: مؤسسة تقترح، أخرى تقر، وثالثة تنظر في نزاع محتمل. لا نختار موقفًا سياسيًا على أنه إجابة واحدة مفروضة؛ بل ننظر في أثر كل جانب: البرلمان — يناقش القانون ويصوت وفق الإجراءات.؛ الإدارة — تنفذ القانون وتدير الخدمة وفق الميزانية.؛ القضاء — يفصل في النزاعات القانونية عند وصولها إليه.. توزيع الوظائف يمنع خلط إصدار القاعدة بتنفيذها والفصل في النزاع، مع اختلاف التفاصيل بين الدساتير.","questions":[{"kind":"choice","prompt":"أي تفسير يطابق جانب «البرلمان» في موقف «ثلاث سلطات في مشروع واحد»؟","target":"مشروع قانون عن المدارس: مؤسسة تقترح، أخرى تقر، وثالثة تنظر في نزاع محتمل.","options":["يناقش القانون ويصوت وفق الإجراءات.","تنفذ القانون وتدير الخدمة وفق الميزانية.","يفصل في النزاعات القانونية عند وصولها إليه.","لا يمكن أن يتأثر هذا الجانب بأي تغيير"],"answerIndex":0,"explanation":"في هذا الجانب: يناقش القانون ويصوت وفق الإجراءات. توزيع الوظائف يمنع خلط إصدار القاعدة بتنفيذها والفصل في النزاع، مع اختلاف التفاصيل بين الدساتير."},{"kind":"choice","prompt":"أي تفسير يطابق جانب «الإدارة» في موقف «ثلاث سلطات في مشروع واحد»؟","target":"مشروع قانون عن المدارس: مؤسسة تقترح، أخرى تقر، وثالثة تنظر في نزاع محتمل.","options":["يناقش القانون ويصوت وفق الإجراءات.","تنفذ القانون وتدير الخدمة وفق الميزانية.","يفصل في النزاعات القانونية عند وصولها إليه.","لا يمكن أن يتأثر هذا الجانب بأي تغيير"],"answerIndex":1,"explanation":"في هذا الجانب: تنفذ القانون وتدير الخدمة وفق الميزانية. توزيع الوظائف يمنع خلط إصدار القاعدة بتنفيذها والفصل في النزاع، مع اختلاف التفاصيل بين الدساتير."},{"kind":"choice","prompt":"أي تفسير يطابق جانب «القضاء» في موقف «ثلاث سلطات في مشروع واحد»؟","target":"مشروع قانون عن المدارس: مؤسسة تقترح، أخرى تقر، وثالثة تنظر في نزاع محتمل.","options":["يناقش القانون ويصوت وفق الإجراءات.","تنفذ القانون وتدير الخدمة وفق الميزانية.","يفصل في النزاعات القانونية عند وصولها إليه.","لا يمكن أن يتأثر هذا الجانب بأي تغيير"],"answerIndex":2,"explanation":"في هذا الجانب: يفصل في النزاعات القانونية عند وصولها إليه. توزيع الوظائف يمنع خلط إصدار القاعدة بتنفيذها والفصل في النزاع، مع اختلاف التفاصيل بين الدساتير."}]},{"slug":"how-state-works","index":4,"title":"السلطة التشريعية","model":"institutions","activity":{"kind":"steps","title":"رحلة مشروع القانون","story":"وصل مقترح جديد إلى مجلس تشريعي. رتّب ما يحدث في مثال إجرائي مبسط.","steps":["دراسة المقترح ومناقشته","التعديل والتصويت وفق القواعد","استكمال إجراءات الإصدار والنشر"],"explain":"بعض الأنظمة تتضمن غرفًا متعددة أو مراجعات إضافية، لكن القانون لا يُنفذ بوصفه تشريعًا قبل استكمال إجراءاته."},"oldBody":"يناقش البرلمان مقترح ضريبة ويعدله ويصوت عليه بدل أن تطبقه جهة إدارية دون سند قانوني.\n\nوالآن تخيّل الموقف التالي: وصل مقترح جديد إلى مجلس تشريعي. رتّب ما يحدث في مثال إجرائي مبسط.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"يناقش البرلمان مقترح ضريبة ويعدله ويصوت عليه بدل أن تطبقه جهة إدارية دون سند قانوني.\n\nوالآن تخيّل الموقف التالي: وصل مقترح جديد إلى مجلس تشريعي. رتّب ما يحدث في مثال إجرائي مبسط.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال محلول: وصل مقترح جديد إلى مجلس تشريعي. رتّب ما يحدث في مثال إجرائي مبسط. الترتيب هنا هو: دراسة المقترح ومناقشته ← التعديل والتصويت وفق القواعد ← استكمال إجراءات الإصدار والنشر. افهم ما تحتاجه كل خطوة من سابقتها، ولماذا يختلف القرار النهائي لو بدأنا بالنتيجة بدل دراسة المعطيات. بعض الأنظمة تتضمن غرفًا متعددة أو مراجعات إضافية، لكن القانون لا يُنفذ بوصفه تشريعًا قبل استكمال إجراءاته.","questions":[{"kind":"choice","prompt":"أي إجراء يسبق بقية الإجراءات في هذا المثال؟","target":"وصل مقترح جديد إلى مجلس تشريعي. رتّب ما يحدث في مثال إجرائي مبسط.","options":["دراسة المقترح ومناقشته","التعديل والتصويت وفق القواعد","استكمال إجراءات الإصدار والنشر","ليس من الضروري ترتيب الإجراءات مطلقًا"],"answerIndex":0,"explanation":"الترتيب في هذا المثال: دراسة المقترح ومناقشته ← التعديل والتصويت وفق القواعد ← استكمال إجراءات الإصدار والنشر. بعض الأنظمة تتضمن غرفًا متعددة أو مراجعات إضافية، لكن القانون لا يُنفذ بوصفه تشريعًا قبل استكمال إجراءاته."},{"kind":"choice","prompt":"ما الإجراء الذي يلي «دراسة المقترح ومناقشته» مباشرة؟","target":"وصل مقترح جديد إلى مجلس تشريعي. رتّب ما يحدث في مثال إجرائي مبسط.","options":["دراسة المقترح ومناقشته","التعديل والتصويت وفق القواعد","استكمال إجراءات الإصدار والنشر","ليس من الضروري ترتيب الإجراءات مطلقًا"],"answerIndex":1,"explanation":"الترتيب في هذا المثال: دراسة المقترح ومناقشته ← التعديل والتصويت وفق القواعد ← استكمال إجراءات الإصدار والنشر. بعض الأنظمة تتضمن غرفًا متعددة أو مراجعات إضافية، لكن القانون لا يُنفذ بوصفه تشريعًا قبل استكمال إجراءاته."},{"kind":"choice","prompt":"ما الإجراء الأخير في هذا التسلسل؟","target":"وصل مقترح جديد إلى مجلس تشريعي. رتّب ما يحدث في مثال إجرائي مبسط.","options":["دراسة المقترح ومناقشته","التعديل والتصويت وفق القواعد","استكمال إجراءات الإصدار والنشر","ليس من الضروري ترتيب الإجراءات مطلقًا"],"answerIndex":2,"explanation":"الترتيب في هذا المثال: دراسة المقترح ومناقشته ← التعديل والتصويت وفق القواعد ← استكمال إجراءات الإصدار والنشر. بعض الأنظمة تتضمن غرفًا متعددة أو مراجعات إضافية، لكن القانون لا يُنفذ بوصفه تشريعًا قبل استكمال إجراءاته."}]},{"slug":"how-state-works","index":5,"title":"السلطة التنفيذية","model":"institutions","activity":{"kind":"case","title":"من ينفذ خدمة الصحة؟","story":"صدر قانون وموازنة لبناء عيادة عامة.","question":"أي جهة تبدأ التنفيذ اليومي للمشروع؟","choices":["محكمة تفصل في قضية جنائية","وزارة أو إدارة تنفيذية مخولة","جهة تكتب الدستور"],"explain":"الجهة التنفيذية تتولى التعاقد والإنفاق والإدارة بحسب القانون، مع خضوعها للرقابة.","correctIndex":1},"oldBody":"تضع وزارة خطة تشغيل مستشفيات بناءً على موازنة وقانون قائمين ثم تتابع تنفيذها.\n\nوالآن تخيّل الموقف التالي: صدر قانون وموازنة لبناء عيادة عامة.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"تضع وزارة خطة تشغيل مستشفيات بناءً على موازنة وقانون قائمين ثم تتابع تنفيذها.\n\nوالآن تخيّل الموقف التالي: صدر قانون وموازنة لبناء عيادة عامة.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال مشروح خطوة بخطوة: صدر قانون وموازنة لبناء عيادة عامة. نبدأ بتحديد السؤال: أي جهة تبدأ التنفيذ اليومي للمشروع؟ ننظر في الخيارات، ثم نبحث عن المعلومة التي يثبتها الواقع أو القانون. في هذا الموقف الإجابة الأدق هي «وزارة أو إدارة تنفيذية مخولة». والسبب: الجهة التنفيذية تتولى التعاقد والإنفاق والإدارة بحسب القانون، مع خضوعها للرقابة.","questions":[{"kind":"choice","prompt":"في حالة «من ينفذ خدمة الصحة؟»: أي جهة تبدأ التنفيذ اليومي للمشروع؟","target":"صدر قانون وموازنة لبناء عيادة عامة.","options":["محكمة تفصل في قضية جنائية","وزارة أو إدارة تنفيذية مخولة","جهة تكتب الدستور","لا علاقة لتلك الخيارات بفهم الموقف"],"answerIndex":1,"explanation":"الجهة التنفيذية تتولى التعاقد والإنفاق والإدارة بحسب القانون، مع خضوعها للرقابة."},{"kind":"choice","prompt":"بعد إقرار ميزانية العيادة، من الجهة التي تتولى العقود والتنفيذ عادة؟","target":"صدر قانون وموازنة لبناء عيادة عامة.","options":["الجهة التنفيذية المختصة ضمن القانون والميزانية","المحكمة التي تفصل في المنازعات","لجنة تعديل الدستور بلا صلاحية تنفيذية","المواطنون بصورة فردية دون جهة مخولة"],"answerIndex":0,"explanation":"الجهة التنفيذية تتولى التعاقد والإنفاق والإدارة بحسب القانون، مع خضوعها للرقابة."}]},{"slug":"how-state-works","index":6,"title":"السلطة القضائية","model":"institutions","activity":{"kind":"case","title":"نزاع على قرار إداري","story":"رُفض ترخيص وفق قرار إداري، وصاحب الطلب يقول إن الإجراءات خالفت القانون.","question":"أي طريق يفحص صحة تطبيق القواعد؟","choices":["المراجعة أو الطعن أمام جهة مختصة بحسب القانون","حذف نص القرار من الموقع","التصويت على السعر في السوق"],"explain":"قد يتيح القانون تظلمًا إداريًا أو قضاءً مختصًا؛ المهم وجود مسار قانوني للفحص.","correctIndex":0},"oldBody":"عندما يطعن مواطن في قرار إداري تنظر المحكمة في الوقائع والقواعد والإجراءات ذات الصلة.\n\nوالآن تخيّل الموقف التالي: رُفض ترخيص وفق قرار إداري، وصاحب الطلب يقول إن الإجراءات خالفت القانون.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"عندما يطعن مواطن في قرار إداري تنظر المحكمة في الوقائع والقواعد والإجراءات ذات الصلة.\n\nوالآن تخيّل الموقف التالي: رُفض ترخيص وفق قرار إداري، وصاحب الطلب يقول إن الإجراءات خالفت القانون.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال مشروح خطوة بخطوة: رُفض ترخيص وفق قرار إداري، وصاحب الطلب يقول إن الإجراءات خالفت القانون. نبدأ بتحديد السؤال: أي طريق يفحص صحة تطبيق القواعد؟ ننظر في الخيارات، ثم نبحث عن المعلومة التي يثبتها الواقع أو القانون. في هذا الموقف الإجابة الأدق هي «المراجعة أو الطعن أمام جهة مختصة بحسب القانون». والسبب: قد يتيح القانون تظلمًا إداريًا أو قضاءً مختصًا؛ المهم وجود مسار قانوني للفحص.","questions":[{"kind":"choice","prompt":"في حالة «نزاع على قرار إداري»: أي طريق يفحص صحة تطبيق القواعد؟","target":"رُفض ترخيص وفق قرار إداري، وصاحب الطلب يقول إن الإجراءات خالفت القانون.","options":["المراجعة أو الطعن أمام جهة مختصة بحسب القانون","حذف نص القرار من الموقع","التصويت على السعر في السوق","لا علاقة لتلك الخيارات بفهم الموقف"],"answerIndex":0,"explanation":"قد يتيح القانون تظلمًا إداريًا أو قضاءً مختصًا؛ المهم وجود مسار قانوني للفحص."},{"kind":"choice","prompt":"ما الفرق بين التظلم القانوني والاعتراض عبر وسائل التواصل؟","target":"رُفض ترخيص وفق قرار إداري، وصاحب الطلب يقول إن الإجراءات خالفت القانون.","options":["التظلم يخضع لمسار مراجعة مختص وفق القانون","وسائل التواصل تلغي القرار قانونًا تلقائيًا","التظلم يمنع أي إمكانية لمراجعة قضائية","تغيير اسم صاحب الطلب يحل النزاع"],"answerIndex":0,"explanation":"قد يتيح القانون تظلمًا إداريًا أو قضاءً مختصًا؛ المهم وجود مسار قانوني للفحص."}]},{"slug":"how-state-works","index":7,"title":"سيادة القانون","model":"institutions","activity":{"kind":"paths","title":"قرار بلا تفسير","story":"تلقّى شخص قرار رفض من إدارة محلية.","question":"قارن ما الذي تتيحه كل آلية للمواطن.","choices":[["قرار معلل","يساعد على فهم السبب ومراجعة القاعدة المطبقة."],["حق التظلم","يتيح طلب مراجعة القرار وفق الإجراءات."],["نشر القواعد","يساعد على توقع الإجراءات قبل التقديم."]],"explain":"سيادة القانون تتصل بوضوح القواعد وإمكان الاحتجاج بها ومراجعة تطبيقها."},"oldBody":"عندما ترفض إدارة طلبًا عليها أن تلتزم بالإجراءات وتتيح طريق تظلم أو مراجعة حيث ينص القانون.\n\nوالآن تخيّل الموقف التالي: تلقّى شخص قرار رفض من إدارة محلية.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"عندما ترفض إدارة طلبًا عليها أن تلتزم بالإجراءات وتتيح طريق تظلم أو مراجعة حيث ينص القانون.\n\nوالآن تخيّل الموقف التالي: تلقّى شخص قرار رفض من إدارة محلية.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال مشروح للمقارنة: تلقّى شخص قرار رفض من إدارة محلية. لا نختار موقفًا سياسيًا على أنه إجابة واحدة مفروضة؛ بل ننظر في أثر كل جانب: قرار معلل — يساعد على فهم السبب ومراجعة القاعدة المطبقة.؛ حق التظلم — يتيح طلب مراجعة القرار وفق الإجراءات.؛ نشر القواعد — يساعد على توقع الإجراءات قبل التقديم.. سيادة القانون تتصل بوضوح القواعد وإمكان الاحتجاج بها ومراجعة تطبيقها.","questions":[{"kind":"choice","prompt":"أي تفسير يطابق جانب «قرار معلل» في موقف «قرار بلا تفسير»؟","target":"تلقّى شخص قرار رفض من إدارة محلية.","options":["يساعد على فهم السبب ومراجعة القاعدة المطبقة.","يتيح طلب مراجعة القرار وفق الإجراءات.","يساعد على توقع الإجراءات قبل التقديم.","لا يمكن أن يتأثر هذا الجانب بأي تغيير"],"answerIndex":0,"explanation":"في هذا الجانب: يساعد على فهم السبب ومراجعة القاعدة المطبقة. سيادة القانون تتصل بوضوح القواعد وإمكان الاحتجاج بها ومراجعة تطبيقها."},{"kind":"choice","prompt":"أي تفسير يطابق جانب «حق التظلم» في موقف «قرار بلا تفسير»؟","target":"تلقّى شخص قرار رفض من إدارة محلية.","options":["يساعد على فهم السبب ومراجعة القاعدة المطبقة.","يتيح طلب مراجعة القرار وفق الإجراءات.","يساعد على توقع الإجراءات قبل التقديم.","لا يمكن أن يتأثر هذا الجانب بأي تغيير"],"answerIndex":1,"explanation":"في هذا الجانب: يتيح طلب مراجعة القرار وفق الإجراءات. سيادة القانون تتصل بوضوح القواعد وإمكان الاحتجاج بها ومراجعة تطبيقها."},{"kind":"choice","prompt":"أي تفسير يطابق جانب «نشر القواعد» في موقف «قرار بلا تفسير»؟","target":"تلقّى شخص قرار رفض من إدارة محلية.","options":["يساعد على فهم السبب ومراجعة القاعدة المطبقة.","يتيح طلب مراجعة القرار وفق الإجراءات.","يساعد على توقع الإجراءات قبل التقديم.","لا يمكن أن يتأثر هذا الجانب بأي تغيير"],"answerIndex":2,"explanation":"في هذا الجانب: يساعد على توقع الإجراءات قبل التقديم. سيادة القانون تتصل بوضوح القواعد وإمكان الاحتجاج بها ومراجعة تطبيقها."}]},{"slug":"how-state-works","index":8,"title":"الإدارة المحلية","model":"institutions","activity":{"kind":"case","title":"من يهتم بالنظافة؟","story":"مدينة تشكو من جمع النفايات. يتولى المجلس المحلي الخدمة بتمويل منصوص عليه.","question":"إلى أي مستوى تتجه الشكوى عن الجدول اليومي أولًا؟","choices":["المجلس المحلي المسؤول عن الخدمة","مفاوض دولي حول معاهدة","بنك مركزي"],"explain":"تعرف الجهة المسؤولة من القانون المحلي لا من حجم الخدمة أو شهرة المؤسسة.","correctIndex":0},"oldBody":"قد يتولى مجلس محلي إدارة النظافة بينما تحدد الدولة المعايير العامة أو التمويل المشترك.\n\nوالآن تخيّل الموقف التالي: مدينة تشكو من جمع النفايات. يتولى المجلس المحلي الخدمة بتمويل منصوص عليه.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"قد يتولى مجلس محلي إدارة النظافة بينما تحدد الدولة المعايير العامة أو التمويل المشترك.\n\nوالآن تخيّل الموقف التالي: مدينة تشكو من جمع النفايات. يتولى المجلس المحلي الخدمة بتمويل منصوص عليه.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال مشروح خطوة بخطوة: مدينة تشكو من جمع النفايات. يتولى المجلس المحلي الخدمة بتمويل منصوص عليه. نبدأ بتحديد السؤال: إلى أي مستوى تتجه الشكوى عن الجدول اليومي أولًا؟ ننظر في الخيارات، ثم نبحث عن المعلومة التي يثبتها الواقع أو القانون. في هذا الموقف الإجابة الأدق هي «المجلس المحلي المسؤول عن الخدمة». والسبب: تعرف الجهة المسؤولة من القانون المحلي لا من حجم الخدمة أو شهرة المؤسسة.","questions":[{"kind":"choice","prompt":"في حالة «من يهتم بالنظافة؟»: إلى أي مستوى تتجه الشكوى عن الجدول اليومي أولًا؟","target":"مدينة تشكو من جمع النفايات. يتولى المجلس المحلي الخدمة بتمويل منصوص عليه.","options":["المجلس المحلي المسؤول عن الخدمة","مفاوض دولي حول معاهدة","بنك مركزي","لا علاقة لتلك الخيارات بفهم الموقف"],"answerIndex":0,"explanation":"تعرف الجهة المسؤولة من القانون المحلي لا من حجم الخدمة أو شهرة المؤسسة."},{"kind":"choice","prompt":"ما الذي يحدد الجهة المسؤولة عن خدمة نظافة في مدينة؟","target":"مدينة تشكو من جمع النفايات. يتولى المجلس المحلي الخدمة بتمويل منصوص عليه.","options":["توزيع اختصاصات الخدمة في الأنظمة المحلية","حجم المدينة وحده دون أي قانون","قرار وزارة الخارجية حول العلاقات الدولية","قائمة أسعار السلع"],"answerIndex":0,"explanation":"تعرف الجهة المسؤولة من القانون المحلي لا من حجم الخدمة أو شهرة المؤسسة."}]},{"slug":"how-state-works","index":9,"title":"المؤسسات والخدمة العامة","model":"institutions","activity":{"kind":"numbers","title":"هل تكفي معدات المدارس؟","story":"إدارة تعليم لديها 20 فصلًا وتريد توزيع الحواسيب.","question":"غيّر عدد الأجهزة وعدد الفصول، وشاهد متوسط الأجهزة لكل فصل.","formula":"distribution","x":{"label":"عدد الأجهزة","min":10,"max":120,"step":10,"initial":40,"unit":"جهاز"},"y":{"label":"عدد الفصول","min":5,"max":30,"step":5,"initial":20,"unit":"فصل"},"explain":"المتوسط لا يكشف وحده إن كانت الأجهزة تعمل أو توزعت بالتساوي؛ هذه أسئلة متابعة مهمة."},"oldBody":"ترصد إدارة مدرسة عدد الطلاب والمعلمين والاحتياجات قبل توزيع الحصص والمعدات.\n\nوالآن تخيّل الموقف التالي: إدارة تعليم لديها 20 فصلًا وتريد توزيع الحواسيب.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"ترصد إدارة مدرسة عدد الطلاب والمعلمين والاحتياجات قبل توزيع الحصص والمعدات.\n\nوالآن تخيّل الموقف التالي: إدارة تعليم لديها 20 فصلًا وتريد توزيع الحواسيب.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال محلول بالأرقام: إدارة تعليم لديها 20 فصلًا وتريد توزيع الحواسيب. نبدأ بقيم عدد الأجهزة = 40 جهاز، وعدد الفصول = 20 فصل. يعطينا النموذج أجهزة لكل فصل: 2 جهاز؛ عدد الفصول: 20 فصل. بعد ذلك غيّر مدخلًا واحدًا وقارن النتيجة بدل توقعها من دون حساب. المتوسط لا يكشف وحده إن كانت الأجهزة تعمل أو توزعت بالتساوي؛ هذه أسئلة متابعة مهمة.","questions":[{"kind":"choice","prompt":"عندما تصبح القيم «عدد الأجهزة: 10 جهاز، عدد الفصول: 5 فصل»، فما قيمة «عدد الفصول»؟","target":"إدارة تعليم لديها 20 فصلًا وتريد توزيع الحواسيب.","options":["5 فصل","6 فصل","4 فصل","7 فصل"],"answerIndex":0,"explanation":"نعوض القيم المعطاة في النموذج المبسط فنحصل على 5 فصل. المتوسط لا يكشف وحده إن كانت الأجهزة تعمل أو توزعت بالتساوي؛ هذه أسئلة متابعة مهمة."},{"kind":"choice","prompt":"عندما تصبح القيم «عدد الأجهزة: 120 جهاز، عدد الفصول: 30 فصل»، فما قيمة «أجهزة لكل فصل»؟","target":"إدارة تعليم لديها 20 فصلًا وتريد توزيع الحواسيب.","options":["4 جهاز","5 جهاز","3 جهاز","6 جهاز"],"answerIndex":0,"explanation":"نعوض القيم المعطاة في النموذج المبسط فنحصل على 4 جهاز. المتوسط لا يكشف وحده إن كانت الأجهزة تعمل أو توزعت بالتساوي؛ هذه أسئلة متابعة مهمة."}]},{"slug":"how-state-works","index":10,"title":"المساءلة والشفافية","model":"institutions","activity":{"kind":"steps","title":"كيف تتحقق من إنفاق جهة؟","story":"نشر جهاز حكومي تقريرًا يقول إنه أنفق موازنة مشروع عام.","steps":["احصل على بيانات الإنفاق","قارن الصرف بالخطة والقواعد","اطلب تفسير الفروق والنتائج"],"explain":"الشفافية توفر معلومات، أما المساءلة فتتطلب سؤال المسؤولين ومراجعة الأداء."},"oldBody":"ينشر جهاز عام تقرير إنفاق ثم تراجع جهة رقابية مدى الالتزام بالإجراءات والنتائج.\n\nوالآن تخيّل الموقف التالي: نشر جهاز حكومي تقريرًا يقول إنه أنفق موازنة مشروع عام.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"ينشر جهاز عام تقرير إنفاق ثم تراجع جهة رقابية مدى الالتزام بالإجراءات والنتائج.\n\nوالآن تخيّل الموقف التالي: نشر جهاز حكومي تقريرًا يقول إنه أنفق موازنة مشروع عام.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال محلول: نشر جهاز حكومي تقريرًا يقول إنه أنفق موازنة مشروع عام. الترتيب هنا هو: احصل على بيانات الإنفاق ← قارن الصرف بالخطة والقواعد ← اطلب تفسير الفروق والنتائج. افهم ما تحتاجه كل خطوة من سابقتها، ولماذا يختلف القرار النهائي لو بدأنا بالنتيجة بدل دراسة المعطيات. الشفافية توفر معلومات، أما المساءلة فتتطلب سؤال المسؤولين ومراجعة الأداء.","questions":[{"kind":"choice","prompt":"أي إجراء يسبق بقية الإجراءات في هذا المثال؟","target":"نشر جهاز حكومي تقريرًا يقول إنه أنفق موازنة مشروع عام.","options":["احصل على بيانات الإنفاق","قارن الصرف بالخطة والقواعد","اطلب تفسير الفروق والنتائج","ليس من الضروري ترتيب الإجراءات مطلقًا"],"answerIndex":0,"explanation":"الترتيب في هذا المثال: احصل على بيانات الإنفاق ← قارن الصرف بالخطة والقواعد ← اطلب تفسير الفروق والنتائج. الشفافية توفر معلومات، أما المساءلة فتتطلب سؤال المسؤولين ومراجعة الأداء."},{"kind":"choice","prompt":"ما الإجراء الذي يلي «احصل على بيانات الإنفاق» مباشرة؟","target":"نشر جهاز حكومي تقريرًا يقول إنه أنفق موازنة مشروع عام.","options":["احصل على بيانات الإنفاق","قارن الصرف بالخطة والقواعد","اطلب تفسير الفروق والنتائج","ليس من الضروري ترتيب الإجراءات مطلقًا"],"answerIndex":1,"explanation":"الترتيب في هذا المثال: احصل على بيانات الإنفاق ← قارن الصرف بالخطة والقواعد ← اطلب تفسير الفروق والنتائج. الشفافية توفر معلومات، أما المساءلة فتتطلب سؤال المسؤولين ومراجعة الأداء."},{"kind":"choice","prompt":"ما الإجراء الأخير في هذا التسلسل؟","target":"نشر جهاز حكومي تقريرًا يقول إنه أنفق موازنة مشروع عام.","options":["احصل على بيانات الإنفاق","قارن الصرف بالخطة والقواعد","اطلب تفسير الفروق والنتائج","ليس من الضروري ترتيب الإجراءات مطلقًا"],"answerIndex":2,"explanation":"الترتيب في هذا المثال: احصل على بيانات الإنفاق ← قارن الصرف بالخطة والقواعد ← اطلب تفسير الفروق والنتائج. الشفافية توفر معلومات، أما المساءلة فتتطلب سؤال المسؤولين ومراجعة الأداء."}]},{"slug":"how-state-works","index":11,"title":"مشروع بناء مؤسسات الدولة","model":"institutions","activity":{"kind":"paths","title":"أنشئ هيئة خدمات","story":"ستؤسس هيئة جديدة لخدمة المواطنين. راجع ثلاث قرارات تأسيسية.","question":"اختر أحد القرارات لتعرف فائدته ومخاطره.","choices":[["تحديد الاختصاص","يوضح ما يجوز للهيئة القيام به ويقلل تضارب المهام."],["تحديد مصادر التمويل","يساعد على استدامة النشاط لكن يلزمه تدقيق."],["إنشاء مسار للشكاوى","يسمح بتصحيح الأخطاء دون افتراض أن كل شكوى صحيحة."]],"explain":"المؤسسات تحتاج قواعد ووظائف وموارد ومراجعة، لا مجرد اسم أو مبنى."},"oldBody":"عند إنشاء هيئة خدمات جديدة تحتاج إلى اختصاص قانوني وميزانية وآلية لتقديم الشكاوى.\n\nوالآن تخيّل الموقف التالي: ستؤسس هيئة جديدة لخدمة المواطنين. راجع ثلاث قرارات تأسيسية.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"عند إنشاء هيئة خدمات جديدة تحتاج إلى اختصاص قانوني وميزانية وآلية لتقديم الشكاوى.\n\nوالآن تخيّل الموقف التالي: ستؤسس هيئة جديدة لخدمة المواطنين. راجع ثلاث قرارات تأسيسية.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال مشروح للمقارنة: ستؤسس هيئة جديدة لخدمة المواطنين. راجع ثلاث قرارات تأسيسية. لا نختار موقفًا سياسيًا على أنه إجابة واحدة مفروضة؛ بل ننظر في أثر كل جانب: تحديد الاختصاص — يوضح ما يجوز للهيئة القيام به ويقلل تضارب المهام.؛ تحديد مصادر التمويل — يساعد على استدامة النشاط لكن يلزمه تدقيق.؛ إنشاء مسار للشكاوى — يسمح بتصحيح الأخطاء دون افتراض أن كل شكوى صحيحة.. المؤسسات تحتاج قواعد ووظائف وموارد ومراجعة، لا مجرد اسم أو مبنى.","questions":[{"kind":"choice","prompt":"أي تفسير يطابق جانب «تحديد الاختصاص» في موقف «أنشئ هيئة خدمات»؟","target":"ستؤسس هيئة جديدة لخدمة المواطنين. راجع ثلاث قرارات تأسيسية.","options":["يوضح ما يجوز للهيئة القيام به ويقلل تضارب المهام.","يساعد على استدامة النشاط لكن يلزمه تدقيق.","يسمح بتصحيح الأخطاء دون افتراض أن كل شكوى صحيحة.","لا يمكن أن يتأثر هذا الجانب بأي تغيير"],"answerIndex":0,"explanation":"في هذا الجانب: يوضح ما يجوز للهيئة القيام به ويقلل تضارب المهام. المؤسسات تحتاج قواعد ووظائف وموارد ومراجعة، لا مجرد اسم أو مبنى."},{"kind":"choice","prompt":"أي تفسير يطابق جانب «تحديد مصادر التمويل» في موقف «أنشئ هيئة خدمات»؟","target":"ستؤسس هيئة جديدة لخدمة المواطنين. راجع ثلاث قرارات تأسيسية.","options":["يوضح ما يجوز للهيئة القيام به ويقلل تضارب المهام.","يساعد على استدامة النشاط لكن يلزمه تدقيق.","يسمح بتصحيح الأخطاء دون افتراض أن كل شكوى صحيحة.","لا يمكن أن يتأثر هذا الجانب بأي تغيير"],"answerIndex":1,"explanation":"في هذا الجانب: يساعد على استدامة النشاط لكن يلزمه تدقيق. المؤسسات تحتاج قواعد ووظائف وموارد ومراجعة، لا مجرد اسم أو مبنى."},{"kind":"choice","prompt":"أي تفسير يطابق جانب «إنشاء مسار للشكاوى» في موقف «أنشئ هيئة خدمات»؟","target":"ستؤسس هيئة جديدة لخدمة المواطنين. راجع ثلاث قرارات تأسيسية.","options":["يوضح ما يجوز للهيئة القيام به ويقلل تضارب المهام.","يساعد على استدامة النشاط لكن يلزمه تدقيق.","يسمح بتصحيح الأخطاء دون افتراض أن كل شكوى صحيحة.","لا يمكن أن يتأثر هذا الجانب بأي تغيير"],"answerIndex":2,"explanation":"في هذا الجانب: يسمح بتصحيح الأخطاء دون افتراض أن كل شكوى صحيحة. المؤسسات تحتاج قواعد ووظائف وموارد ومراجعة، لا مجرد اسم أو مبنى."}]},{"slug":"political-systems","index":0,"title":"الجمهورية والملكية","model":"elections","activity":{"kind":"case","title":"هل اسم المنصب يكفي؟","story":"بلد ملكي يملك فيه البرلمان سلطة اختيار الحكومة، وبلد جمهوري يدير فيه الرئيس الحكومة.","question":"ما الذي يجب فحصه قبل مقارنة الصلاحيات؟","choices":["اسم الملك أو الرئيس فقط","النصوص الدستورية ومسؤولية الحكومة","عدد الأعلام"],"explain":"الملكية والجمهورية تصفان رأس الدولة، أما صلاحيات الحكومة فتحتاج قراءة مؤسسات الحكم.","correctIndex":1},"oldBody":"قد يكون الملك صاحب دور رمزي في نظام برلماني، بينما يتمتع رئيس جمهورية بصلاحيات تنفيذية أوسع في نظام آخر.\n\nوالآن تخيّل الموقف التالي: بلد ملكي يملك فيه البرلمان سلطة اختيار الحكومة، وبلد جمهوري يدير فيه الرئيس الحكومة.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"قد يكون الملك صاحب دور رمزي في نظام برلماني، بينما يتمتع رئيس جمهورية بصلاحيات تنفيذية أوسع في نظام آخر.\n\nوالآن تخيّل الموقف التالي: بلد ملكي يملك فيه البرلمان سلطة اختيار الحكومة، وبلد جمهوري يدير فيه الرئيس الحكومة.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال مشروح خطوة بخطوة: بلد ملكي يملك فيه البرلمان سلطة اختيار الحكومة، وبلد جمهوري يدير فيه الرئيس الحكومة. نبدأ بتحديد السؤال: ما الذي يجب فحصه قبل مقارنة الصلاحيات؟ ننظر في الخيارات، ثم نبحث عن المعلومة التي يثبتها الواقع أو القانون. في هذا الموقف الإجابة الأدق هي «النصوص الدستورية ومسؤولية الحكومة». والسبب: الملكية والجمهورية تصفان رأس الدولة، أما صلاحيات الحكومة فتحتاج قراءة مؤسسات الحكم.","questions":[{"kind":"choice","prompt":"في حالة «هل اسم المنصب يكفي؟»: ما الذي يجب فحصه قبل مقارنة الصلاحيات؟","target":"بلد ملكي يملك فيه البرلمان سلطة اختيار الحكومة، وبلد جمهوري يدير فيه الرئيس الحكومة.","options":["اسم الملك أو الرئيس فقط","النصوص الدستورية ومسؤولية الحكومة","عدد الأعلام","لا علاقة لتلك الخيارات بفهم الموقف"],"answerIndex":1,"explanation":"الملكية والجمهورية تصفان رأس الدولة، أما صلاحيات الحكومة فتحتاج قراءة مؤسسات الحكم."},{"kind":"choice","prompt":"لماذا لا يكفي وصف الدولة بأنها ملكية أو جمهورية للمقارنة؟","target":"بلد ملكي يملك فيه البرلمان سلطة اختيار الحكومة، وبلد جمهوري يدير فيه الرئيس الحكومة.","options":["لأن الصلاحيات الفعلية تحددها القواعد الدستورية والمؤسسات","لأن كل الملكيات لها الحكومة نفسها","لأن كل الجمهوريات تمنع وجود البرلمان","لأن السلطة القضائية غير مهمة"],"answerIndex":0,"explanation":"الملكية والجمهورية تصفان رأس الدولة، أما صلاحيات الحكومة فتحتاج قراءة مؤسسات الحكم."}]},{"slug":"political-systems","index":1,"title":"النظام الرئاسي","model":"elections","activity":{"kind":"case","title":"رئيس وبرلمان منتخبَان","story":"في نظام افتراضي ينتخب المواطنون الرئيس والبرلمان كلًا على حدة.","question":"أي وصف ينسجم مع الصورة العامة للنظام الرئاسي؟","choices":["تنشأ الحكومة حتمًا من تصويت ثقة البرلمان","يقود الرئيس التنفيذ مع فصل دستوري للسلطات","لا وجود لقضاء"],"explain":"الانتخاب المنفصل من خصائص الأنظمة الرئاسية عادة، مع فروق تفصيلية بين الدول.","correctIndex":1},"oldBody":"قد ينتخب المواطنون رئيسًا وبرلمانًا على نحو منفصل فيختلف الانتماء الحزبي بين المؤسستين.\n\nوالآن تخيّل الموقف التالي: في نظام افتراضي ينتخب المواطنون الرئيس والبرلمان كلًا على حدة.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"قد ينتخب المواطنون رئيسًا وبرلمانًا على نحو منفصل فيختلف الانتماء الحزبي بين المؤسستين.\n\nوالآن تخيّل الموقف التالي: في نظام افتراضي ينتخب المواطنون الرئيس والبرلمان كلًا على حدة.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال مشروح خطوة بخطوة: في نظام افتراضي ينتخب المواطنون الرئيس والبرلمان كلًا على حدة. نبدأ بتحديد السؤال: أي وصف ينسجم مع الصورة العامة للنظام الرئاسي؟ ننظر في الخيارات، ثم نبحث عن المعلومة التي يثبتها الواقع أو القانون. في هذا الموقف الإجابة الأدق هي «يقود الرئيس التنفيذ مع فصل دستوري للسلطات». والسبب: الانتخاب المنفصل من خصائص الأنظمة الرئاسية عادة، مع فروق تفصيلية بين الدول.","questions":[{"kind":"choice","prompt":"في حالة «رئيس وبرلمان منتخبَان»: أي وصف ينسجم مع الصورة العامة للنظام الرئاسي؟","target":"في نظام افتراضي ينتخب المواطنون الرئيس والبرلمان كلًا على حدة.","options":["تنشأ الحكومة حتمًا من تصويت ثقة البرلمان","يقود الرئيس التنفيذ مع فصل دستوري للسلطات","لا وجود لقضاء","لا علاقة لتلك الخيارات بفهم الموقف"],"answerIndex":1,"explanation":"الانتخاب المنفصل من خصائص الأنظمة الرئاسية عادة، مع فروق تفصيلية بين الدول."},{"kind":"choice","prompt":"ماذا يعني انتخاب الرئيس والبرلمان كلًّا على حدة في المثال؟","target":"في نظام افتراضي ينتخب المواطنون الرئيس والبرلمان كلًا على حدة.","options":["وجود تفويضين انتخابيين منفصلين ضمن قواعد الدستور","أن الرئيس لا يخضع لأي قانون","أن السلطة التشريعية لا تنتخب أصلًا","أن القضاة يصدرون القوانين بدل البرلمان"],"answerIndex":0,"explanation":"الانتخاب المنفصل من خصائص الأنظمة الرئاسية عادة، مع فروق تفصيلية بين الدول."}]},{"slug":"political-systems","index":2,"title":"النظام البرلماني","model":"elections","activity":{"kind":"steps","title":"تشكيل حكومة برلمانية","story":"أفرزت الانتخابات مجلسًا لا يملك فيه أي حزب أكثر من نصف المقاعد.","steps":["تراجع الأحزاب نتائج المقاعد","تتفاوض على ائتلاف أو دعم برلماني","تُطرح الحكومة لثقة المجلس وفق القواعد"],"explain":"الائتلاف وسيلة للحصول على دعم برلماني ولا يعني ذوبان برامج الأحزاب."},"oldBody":"تفاوض أحزاب على اتفاق ائتلاف لتشكيل وزارة تحصل على ثقة المجلس المنتخب.\n\nوالآن تخيّل الموقف التالي: أفرزت الانتخابات مجلسًا لا يملك فيه أي حزب أكثر من نصف المقاعد.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"تفاوض أحزاب على اتفاق ائتلاف لتشكيل وزارة تحصل على ثقة المجلس المنتخب.\n\nوالآن تخيّل الموقف التالي: أفرزت الانتخابات مجلسًا لا يملك فيه أي حزب أكثر من نصف المقاعد.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال محلول: أفرزت الانتخابات مجلسًا لا يملك فيه أي حزب أكثر من نصف المقاعد. الترتيب هنا هو: تراجع الأحزاب نتائج المقاعد ← تتفاوض على ائتلاف أو دعم برلماني ← تُطرح الحكومة لثقة المجلس وفق القواعد. افهم ما تحتاجه كل خطوة من سابقتها، ولماذا يختلف القرار النهائي لو بدأنا بالنتيجة بدل دراسة المعطيات. الائتلاف وسيلة للحصول على دعم برلماني ولا يعني ذوبان برامج الأحزاب.","questions":[{"kind":"choice","prompt":"أي إجراء يسبق بقية الإجراءات في هذا المثال؟","target":"أفرزت الانتخابات مجلسًا لا يملك فيه أي حزب أكثر من نصف المقاعد.","options":["تراجع الأحزاب نتائج المقاعد","تتفاوض على ائتلاف أو دعم برلماني","تُطرح الحكومة لثقة المجلس وفق القواعد","ليس من الضروري ترتيب الإجراءات مطلقًا"],"answerIndex":0,"explanation":"الترتيب في هذا المثال: تراجع الأحزاب نتائج المقاعد ← تتفاوض على ائتلاف أو دعم برلماني ← تُطرح الحكومة لثقة المجلس وفق القواعد. الائتلاف وسيلة للحصول على دعم برلماني ولا يعني ذوبان برامج الأحزاب."},{"kind":"choice","prompt":"ما الإجراء الذي يلي «تراجع الأحزاب نتائج المقاعد» مباشرة؟","target":"أفرزت الانتخابات مجلسًا لا يملك فيه أي حزب أكثر من نصف المقاعد.","options":["تراجع الأحزاب نتائج المقاعد","تتفاوض على ائتلاف أو دعم برلماني","تُطرح الحكومة لثقة المجلس وفق القواعد","ليس من الضروري ترتيب الإجراءات مطلقًا"],"answerIndex":1,"explanation":"الترتيب في هذا المثال: تراجع الأحزاب نتائج المقاعد ← تتفاوض على ائتلاف أو دعم برلماني ← تُطرح الحكومة لثقة المجلس وفق القواعد. الائتلاف وسيلة للحصول على دعم برلماني ولا يعني ذوبان برامج الأحزاب."},{"kind":"choice","prompt":"ما الإجراء الأخير في هذا التسلسل؟","target":"أفرزت الانتخابات مجلسًا لا يملك فيه أي حزب أكثر من نصف المقاعد.","options":["تراجع الأحزاب نتائج المقاعد","تتفاوض على ائتلاف أو دعم برلماني","تُطرح الحكومة لثقة المجلس وفق القواعد","ليس من الضروري ترتيب الإجراءات مطلقًا"],"answerIndex":2,"explanation":"الترتيب في هذا المثال: تراجع الأحزاب نتائج المقاعد ← تتفاوض على ائتلاف أو دعم برلماني ← تُطرح الحكومة لثقة المجلس وفق القواعد. الائتلاف وسيلة للحصول على دعم برلماني ولا يعني ذوبان برامج الأحزاب."}]},{"slug":"political-systems","index":3,"title":"النظام شبه الرئاسي","model":"elections","activity":{"kind":"case","title":"رئيس ورئيس وزراء","story":"لدولة رئيس منتخب مباشرة ورئيس وزراء تحتاج حكومته ثقة البرلمان.","question":"ما العامل الحاسم لتحديد دور كل طرف؟","choices":["النص الدستوري ونطاق صلاحيات كل منصب","طول اسم الدولة","اللون المفضل للوزير"],"explain":"في شبه الرئاسي تتغير علاقة الطرفين بحسب الدستور وتوازن البرلمان، فلا يكفي اسم المنصب.","correctIndex":0},"oldBody":"قد تتقاسم مؤسسة الرئاسة ورئاسة الحكومة صلاحيات تختلف بحسب الدستور والائتلاف البرلماني.\n\nوالآن تخيّل الموقف التالي: لدولة رئيس منتخب مباشرة ورئيس وزراء تحتاج حكومته ثقة البرلمان.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"قد تتقاسم مؤسسة الرئاسة ورئاسة الحكومة صلاحيات تختلف بحسب الدستور والائتلاف البرلماني.\n\nوالآن تخيّل الموقف التالي: لدولة رئيس منتخب مباشرة ورئيس وزراء تحتاج حكومته ثقة البرلمان.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال مشروح خطوة بخطوة: لدولة رئيس منتخب مباشرة ورئيس وزراء تحتاج حكومته ثقة البرلمان. نبدأ بتحديد السؤال: ما العامل الحاسم لتحديد دور كل طرف؟ ننظر في الخيارات، ثم نبحث عن المعلومة التي يثبتها الواقع أو القانون. في هذا الموقف الإجابة الأدق هي «النص الدستوري ونطاق صلاحيات كل منصب». والسبب: في شبه الرئاسي تتغير علاقة الطرفين بحسب الدستور وتوازن البرلمان، فلا يكفي اسم المنصب.","questions":[{"kind":"choice","prompt":"في حالة «رئيس ورئيس وزراء»: ما العامل الحاسم لتحديد دور كل طرف؟","target":"لدولة رئيس منتخب مباشرة ورئيس وزراء تحتاج حكومته ثقة البرلمان.","options":["النص الدستوري ونطاق صلاحيات كل منصب","طول اسم الدولة","اللون المفضل للوزير","لا علاقة لتلك الخيارات بفهم الموقف"],"answerIndex":0,"explanation":"في شبه الرئاسي تتغير علاقة الطرفين بحسب الدستور وتوازن البرلمان، فلا يكفي اسم المنصب."},{"kind":"choice","prompt":"كيف نعرف حدود اختصاص رئيس الجمهورية ورئيس الوزراء؟","target":"لدولة رئيس منتخب مباشرة ورئيس وزراء تحتاج حكومته ثقة البرلمان.","options":["من النصوص الدستورية وآلية الثقة البرلمانية وتوزيع الصلاحيات","من عدد حروف اسم منصبيهما","من ترتيب ظهورهما في الأخبار فقط","من لون الشعار الرسمي"],"answerIndex":0,"explanation":"في شبه الرئاسي تتغير علاقة الطرفين بحسب الدستور وتوازن البرلمان، فلا يكفي اسم المنصب."}]},{"slug":"political-systems","index":4,"title":"الدولة الموحدة والفيدرالية","model":"elections","activity":{"kind":"paths","title":"خدمة التعليم بين المستويات","story":"نظام فيدرالي يحدد دستوره صلاحيات الاتحاد والأقاليم.","question":"اختر جانبًا لفحص توزيعه.","choices":[["المناهج التعليمية","قد توزع بين الاتحاد والإقليم بحسب الدستور."],["التمويل","قد يكون محليًا أو مشتركًا مع قواعد تحويل."],["حل الخلاف","تحتاج الأطراف إلى آلية دستورية للفصل."]],"explain":"الفيدرالية ليست استقلال الأقاليم عن الدولة، والتفاصيل تختلف بين البلدان."},"oldBody":"يمكن لإقليم في نظام فيدرالي أن يدير بعض الخدمات بقواعده ضمن اختصاصه الدستوري.\n\nوالآن تخيّل الموقف التالي: نظام فيدرالي يحدد دستوره صلاحيات الاتحاد والأقاليم.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"يمكن لإقليم في نظام فيدرالي أن يدير بعض الخدمات بقواعده ضمن اختصاصه الدستوري.\n\nوالآن تخيّل الموقف التالي: نظام فيدرالي يحدد دستوره صلاحيات الاتحاد والأقاليم.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال مشروح للمقارنة: نظام فيدرالي يحدد دستوره صلاحيات الاتحاد والأقاليم. لا نختار موقفًا سياسيًا على أنه إجابة واحدة مفروضة؛ بل ننظر في أثر كل جانب: المناهج التعليمية — قد توزع بين الاتحاد والإقليم بحسب الدستور.؛ التمويل — قد يكون محليًا أو مشتركًا مع قواعد تحويل.؛ حل الخلاف — تحتاج الأطراف إلى آلية دستورية للفصل.. الفيدرالية ليست استقلال الأقاليم عن الدولة، والتفاصيل تختلف بين البلدان.","questions":[{"kind":"choice","prompt":"أي تفسير يطابق جانب «المناهج التعليمية» في موقف «خدمة التعليم بين المستويات»؟","target":"نظام فيدرالي يحدد دستوره صلاحيات الاتحاد والأقاليم.","options":["قد توزع بين الاتحاد والإقليم بحسب الدستور.","قد يكون محليًا أو مشتركًا مع قواعد تحويل.","تحتاج الأطراف إلى آلية دستورية للفصل.","لا يمكن أن يتأثر هذا الجانب بأي تغيير"],"answerIndex":0,"explanation":"في هذا الجانب: قد توزع بين الاتحاد والإقليم بحسب الدستور. الفيدرالية ليست استقلال الأقاليم عن الدولة، والتفاصيل تختلف بين البلدان."},{"kind":"choice","prompt":"أي تفسير يطابق جانب «التمويل» في موقف «خدمة التعليم بين المستويات»؟","target":"نظام فيدرالي يحدد دستوره صلاحيات الاتحاد والأقاليم.","options":["قد توزع بين الاتحاد والإقليم بحسب الدستور.","قد يكون محليًا أو مشتركًا مع قواعد تحويل.","تحتاج الأطراف إلى آلية دستورية للفصل.","لا يمكن أن يتأثر هذا الجانب بأي تغيير"],"answerIndex":1,"explanation":"في هذا الجانب: قد يكون محليًا أو مشتركًا مع قواعد تحويل. الفيدرالية ليست استقلال الأقاليم عن الدولة، والتفاصيل تختلف بين البلدان."},{"kind":"choice","prompt":"أي تفسير يطابق جانب «حل الخلاف» في موقف «خدمة التعليم بين المستويات»؟","target":"نظام فيدرالي يحدد دستوره صلاحيات الاتحاد والأقاليم.","options":["قد توزع بين الاتحاد والإقليم بحسب الدستور.","قد يكون محليًا أو مشتركًا مع قواعد تحويل.","تحتاج الأطراف إلى آلية دستورية للفصل.","لا يمكن أن يتأثر هذا الجانب بأي تغيير"],"answerIndex":2,"explanation":"في هذا الجانب: تحتاج الأطراف إلى آلية دستورية للفصل. الفيدرالية ليست استقلال الأقاليم عن الدولة، والتفاصيل تختلف بين البلدان."}]},{"slug":"political-systems","index":5,"title":"اللامركزية الإدارية والسياسية","model":"elections","activity":{"kind":"case","title":"صلاحيات بلدية","story":"بلدية تدير الطرق والنظافة محليًا، ولكنها لا تملك توقيع اتفاقيات دفاعية.","question":"ما الوصف الأدق لوظيفتها؟","choices":["لامركزية إدارية ضمن اختصاص مقرر","سيادة دولية كاملة","سلطة قضائية وطنية"],"explain":"نقل الإدارة المحلية لا يعني منح كل صلاحيات الدولة إلى البلدية.","correctIndex":0},"oldBody":"قد تدير بلدية الطرق المحلية دون أن تملك سلطة إصدار قوانين وطنية أو عقد معاهدات.\n\nوالآن تخيّل الموقف التالي: بلدية تدير الطرق والنظافة محليًا، ولكنها لا تملك توقيع اتفاقيات دفاعية.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"قد تدير بلدية الطرق المحلية دون أن تملك سلطة إصدار قوانين وطنية أو عقد معاهدات.\n\nوالآن تخيّل الموقف التالي: بلدية تدير الطرق والنظافة محليًا، ولكنها لا تملك توقيع اتفاقيات دفاعية.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال مشروح خطوة بخطوة: بلدية تدير الطرق والنظافة محليًا، ولكنها لا تملك توقيع اتفاقيات دفاعية. نبدأ بتحديد السؤال: ما الوصف الأدق لوظيفتها؟ ننظر في الخيارات، ثم نبحث عن المعلومة التي يثبتها الواقع أو القانون. في هذا الموقف الإجابة الأدق هي «لامركزية إدارية ضمن اختصاص مقرر». والسبب: نقل الإدارة المحلية لا يعني منح كل صلاحيات الدولة إلى البلدية.","questions":[{"kind":"choice","prompt":"في حالة «صلاحيات بلدية»: ما الوصف الأدق لوظيفتها؟","target":"بلدية تدير الطرق والنظافة محليًا، ولكنها لا تملك توقيع اتفاقيات دفاعية.","options":["لامركزية إدارية ضمن اختصاص مقرر","سيادة دولية كاملة","سلطة قضائية وطنية","لا علاقة لتلك الخيارات بفهم الموقف"],"answerIndex":0,"explanation":"نقل الإدارة المحلية لا يعني منح كل صلاحيات الدولة إلى البلدية."},{"kind":"choice","prompt":"ما الذي لا ينتج تلقائيًا عن منح البلدية إدارة الطرق؟","target":"بلدية تدير الطرق والنظافة محليًا، ولكنها لا تملك توقيع اتفاقيات دفاعية.","options":["لا يعني ذلك منحها حق توقيع اتفاق دفاعي باسم الدولة","تصبح مسؤولة عن الطريق المحلي ضمن القانون","قد تحتاج إلى تمويل ورقابة محليين","يمكن توزيع الاختصاصات بين مستويات الحكومة"],"answerIndex":0,"explanation":"نقل الإدارة المحلية لا يعني منح كل صلاحيات الدولة إلى البلدية."}]},{"slug":"political-systems","index":6,"title":"الأحزاب والتعددية","model":"elections","activity":{"kind":"paths","title":"ثلاثة برامج انتخابية","story":"أحزاب افتراضية تعرض أولويات مختلفة بشأن النقل والإسكان والضرائب.","question":"ما الذي يمكن مقارنته بصورة محايدة؟","choices":[["التكلفة","هل توضح كل خطة مصادر التمويل؟"],["التنفيذ","من الجهة المسؤولة وفي أي مدة؟"],["النتائج","ما المؤشرات التي يمكن قياسها بعد التنفيذ؟"]],"explain":"الفحص المقارن يقيم الادعاءات والأدلة لا يقرر للناخب أي حزب يختار."},"oldBody":"قد تقدم ثلاثة أحزاب برامج مختلفة حول الضرائب ثم تتفاوض على نقاط مشتركة بعد الانتخابات.\n\nوالآن تخيّل الموقف التالي: أحزاب افتراضية تعرض أولويات مختلفة بشأن النقل والإسكان والضرائب.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"قد تقدم ثلاثة أحزاب برامج مختلفة حول الضرائب ثم تتفاوض على نقاط مشتركة بعد الانتخابات.\n\nوالآن تخيّل الموقف التالي: أحزاب افتراضية تعرض أولويات مختلفة بشأن النقل والإسكان والضرائب.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال مشروح للمقارنة: أحزاب افتراضية تعرض أولويات مختلفة بشأن النقل والإسكان والضرائب. لا نختار موقفًا سياسيًا على أنه إجابة واحدة مفروضة؛ بل ننظر في أثر كل جانب: التكلفة — هل توضح كل خطة مصادر التمويل؟؛ التنفيذ — من الجهة المسؤولة وفي أي مدة؟؛ النتائج — ما المؤشرات التي يمكن قياسها بعد التنفيذ؟. الفحص المقارن يقيم الادعاءات والأدلة لا يقرر للناخب أي حزب يختار.","questions":[{"kind":"choice","prompt":"أي تفسير يطابق جانب «التكلفة» في موقف «ثلاثة برامج انتخابية»؟","target":"أحزاب افتراضية تعرض أولويات مختلفة بشأن النقل والإسكان والضرائب.","options":["هل توضح كل خطة مصادر التمويل؟","من الجهة المسؤولة وفي أي مدة؟","ما المؤشرات التي يمكن قياسها بعد التنفيذ؟","لا يمكن أن يتأثر هذا الجانب بأي تغيير"],"answerIndex":0,"explanation":"في هذا الجانب: هل توضح كل خطة مصادر التمويل؟ الفحص المقارن يقيم الادعاءات والأدلة لا يقرر للناخب أي حزب يختار."},{"kind":"choice","prompt":"أي تفسير يطابق جانب «التنفيذ» في موقف «ثلاثة برامج انتخابية»؟","target":"أحزاب افتراضية تعرض أولويات مختلفة بشأن النقل والإسكان والضرائب.","options":["هل توضح كل خطة مصادر التمويل؟","من الجهة المسؤولة وفي أي مدة؟","ما المؤشرات التي يمكن قياسها بعد التنفيذ؟","لا يمكن أن يتأثر هذا الجانب بأي تغيير"],"answerIndex":1,"explanation":"في هذا الجانب: من الجهة المسؤولة وفي أي مدة؟ الفحص المقارن يقيم الادعاءات والأدلة لا يقرر للناخب أي حزب يختار."},{"kind":"choice","prompt":"أي تفسير يطابق جانب «النتائج» في موقف «ثلاثة برامج انتخابية»؟","target":"أحزاب افتراضية تعرض أولويات مختلفة بشأن النقل والإسكان والضرائب.","options":["هل توضح كل خطة مصادر التمويل؟","من الجهة المسؤولة وفي أي مدة؟","ما المؤشرات التي يمكن قياسها بعد التنفيذ؟","لا يمكن أن يتأثر هذا الجانب بأي تغيير"],"answerIndex":2,"explanation":"في هذا الجانب: ما المؤشرات التي يمكن قياسها بعد التنفيذ؟ الفحص المقارن يقيم الادعاءات والأدلة لا يقرر للناخب أي حزب يختار."}]},{"slug":"political-systems","index":7,"title":"الانتخابات والتمثيل","model":"elections","activity":{"kind":"numbers","title":"وزع المقاعد انتخابيًا","story":"ثلاث قوائم تتنافس على عشرة مقاعد في دائرة واحدة.","question":"غير أصوات قائمتين وانظر كيف توزع طريقة دونت المقاعد.","formula":"dhondt","x":{"label":"القائمة أ (%)","min":10,"max":70,"step":5,"initial":40,"unit":"%"},"y":{"label":"القائمة ب (%)","min":10,"max":70,"step":5,"initial":35,"unit":"%"},"explain":"هذا نموذج مبسط لطريقة دونت دون عتبة ولا دوائر متعددة. النتائج ليست توقعًا سياسيًا."},"oldBody":"قد تحصل قائمة على نسبة من المقاعد تختلف عن نسبتها من الأصوات بسبب طريقة توزيع المقاعد.\n\nوالآن تخيّل الموقف التالي: ثلاث قوائم تتنافس على عشرة مقاعد في دائرة واحدة.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"قد تحصل قائمة على نسبة من المقاعد تختلف عن نسبتها من الأصوات بسبب طريقة توزيع المقاعد.\n\nوالآن تخيّل الموقف التالي: ثلاث قوائم تتنافس على عشرة مقاعد في دائرة واحدة.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال محلول بالأرقام: ثلاث قوائم تتنافس على عشرة مقاعد في دائرة واحدة. نبدأ بقيم القائمة أ (%) = 40 %، والقائمة ب (%) = 35 %. يعطينا النموذج القائمة أ: 4 مقاعد (40% من الأصوات)؛ القائمة ب: 4 مقاعد (35% من الأصوات)؛ القائمة ج: 2 مقاعد (25% من الأصوات). بعد ذلك غيّر مدخلًا واحدًا وقارن النتيجة بدل توقعها من دون حساب. هذا نموذج مبسط لطريقة دونت دون عتبة ولا دوائر متعددة. النتائج ليست توقعًا سياسيًا.","questions":[{"kind":"choice","prompt":"عندما تصبح القيم «القائمة أ (%): 10 %، القائمة ب (%): 10 %»، فما قيمة «القائمة أ»؟","target":"ثلاث قوائم تتنافس على عشرة مقاعد في دائرة واحدة.","options":["1 مقاعد (10% من الأصوات)","2 مقاعد (10% من الأصوات)","0 مقاعد (10% من الأصوات)","3 مقاعد (10% من الأصوات)"],"answerIndex":0,"explanation":"نعوض القيم المعطاة في النموذج المبسط فنحصل على 1 مقاعد (10% من الأصوات). هذا نموذج مبسط لطريقة دونت دون عتبة ولا دوائر متعددة. النتائج ليست توقعًا سياسيًا."},{"kind":"choice","prompt":"عندما تصبح القيم «القائمة أ (%): 70 %، القائمة ب (%): 25 %»، فما قيمة «القائمة أ»؟","target":"ثلاث قوائم تتنافس على عشرة مقاعد في دائرة واحدة.","options":["8 مقاعد (70% من الأصوات)","9 مقاعد (70% من الأصوات)","7 مقاعد (70% من الأصوات)","10 مقاعد (70% من الأصوات)"],"answerIndex":0,"explanation":"نعوض القيم المعطاة في النموذج المبسط فنحصل على 8 مقاعد (70% من الأصوات). هذا نموذج مبسط لطريقة دونت دون عتبة ولا دوائر متعددة. النتائج ليست توقعًا سياسيًا."}]},{"slug":"political-systems","index":8,"title":"الائتلافات والحكومات","model":"elections","activity":{"kind":"numbers","title":"ابن ائتلافًا","story":"مجلس من عشرة مقاعد؛ عدد مقاعد القوائم يتغير وفق أصوات الناخبين.","question":"غير نسب الأصوات ثم ابحث عن ائتلاف يبلغ ستة مقاعد.","formula":"coalition","x":{"label":"القائمة أ (%)","min":10,"max":70,"step":5,"initial":35,"unit":"%"},"y":{"label":"القائمة ب (%)","min":10,"max":70,"step":5,"initial":35,"unit":"%"},"explain":"حساب الأغلبية لا يكشف مدى اتفاق الأحزاب في البرامج؛ الائتلاف يحتاج أيضًا تفاوضًا."},"oldBody":"تتفاوض قائمتان على خطة مشتركة لخدمات عامة كي تحصلا معًا على أغلبية المقاعد.\n\nوالآن تخيّل الموقف التالي: مجلس من عشرة مقاعد؛ عدد مقاعد القوائم يتغير وفق أصوات الناخبين.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"تتفاوض قائمتان على خطة مشتركة لخدمات عامة كي تحصلا معًا على أغلبية المقاعد.\n\nوالآن تخيّل الموقف التالي: مجلس من عشرة مقاعد؛ عدد مقاعد القوائم يتغير وفق أصوات الناخبين.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال محلول بالأرقام: مجلس من عشرة مقاعد؛ عدد مقاعد القوائم يتغير وفق أصوات الناخبين. نبدأ بقيم القائمة أ (%) = 35 %، والقائمة ب (%) = 35 %. يعطينا النموذج القائمة أ: 4 مقاعد (35% من الأصوات)؛ القائمة ب: 3 مقاعد (35% من الأصوات)؛ القائمة ج: 3 مقاعد (30% من الأصوات)؛ أكبر ائتلاف من قائمتين: 7 مقاعد. بعد ذلك غيّر مدخلًا واحدًا وقارن النتيجة بدل توقعها من دون حساب. حساب الأغلبية لا يكشف مدى اتفاق الأحزاب في البرامج؛ الائتلاف يحتاج أيضًا تفاوضًا.","questions":[{"kind":"choice","prompt":"عندما تصبح القيم «القائمة أ (%): 10 %، القائمة ب (%): 10 %»، فما قيمة «القائمة أ»؟","target":"مجلس من عشرة مقاعد؛ عدد مقاعد القوائم يتغير وفق أصوات الناخبين.","options":["1 مقاعد (10% من الأصوات)","2 مقاعد (10% من الأصوات)","0 مقاعد (10% من الأصوات)","3 مقاعد (10% من الأصوات)"],"answerIndex":0,"explanation":"نعوض القيم المعطاة في النموذج المبسط فنحصل على 1 مقاعد (10% من الأصوات). حساب الأغلبية لا يكشف مدى اتفاق الأحزاب في البرامج؛ الائتلاف يحتاج أيضًا تفاوضًا."},{"kind":"choice","prompt":"عندما تصبح القيم «القائمة أ (%): 70 %، القائمة ب (%): 25 %»، فما قيمة «القائمة أ»؟","target":"مجلس من عشرة مقاعد؛ عدد مقاعد القوائم يتغير وفق أصوات الناخبين.","options":["8 مقاعد (70% من الأصوات)","9 مقاعد (70% من الأصوات)","7 مقاعد (70% من الأصوات)","10 مقاعد (70% من الأصوات)"],"answerIndex":0,"explanation":"نعوض القيم المعطاة في النموذج المبسط فنحصل على 8 مقاعد (70% من الأصوات). حساب الأغلبية لا يكشف مدى اتفاق الأحزاب في البرامج؛ الائتلاف يحتاج أيضًا تفاوضًا."}]},{"slug":"political-systems","index":9,"title":"المعارضة والرقابة","model":"elections","activity":{"kind":"steps","title":"سؤال رقابي","story":"عضو في البرلمان يسأل وزيرًا عن تكلفة طريق. كيف تُفحص الإجابة؟","steps":["اطلب تفاصيل المشروع والتمويل","راجع التقرير والمستندات","قارن الإجابة بالوقائع واطرح أسئلة متابعة"],"explain":"الرقابة الجيدة تقارن الأدلة دون افتراض مسبق أن رد الوزير أو المعارض صحيح."},"oldBody":"يسأل نائب معارض وزيرًا عن تكلفة مشروع ويطلب نشر التقارير ثم يناقشها المجلس.\n\nوالآن تخيّل الموقف التالي: عضو في البرلمان يسأل وزيرًا عن تكلفة طريق. كيف تُفحص الإجابة؟\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"يسأل نائب معارض وزيرًا عن تكلفة مشروع ويطلب نشر التقارير ثم يناقشها المجلس.\n\nوالآن تخيّل الموقف التالي: عضو في البرلمان يسأل وزيرًا عن تكلفة طريق. كيف تُفحص الإجابة؟\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال محلول: عضو في البرلمان يسأل وزيرًا عن تكلفة طريق. كيف تُفحص الإجابة؟ الترتيب هنا هو: اطلب تفاصيل المشروع والتمويل ← راجع التقرير والمستندات ← قارن الإجابة بالوقائع واطرح أسئلة متابعة. افهم ما تحتاجه كل خطوة من سابقتها، ولماذا يختلف القرار النهائي لو بدأنا بالنتيجة بدل دراسة المعطيات. الرقابة الجيدة تقارن الأدلة دون افتراض مسبق أن رد الوزير أو المعارض صحيح.","questions":[{"kind":"choice","prompt":"أي إجراء يسبق بقية الإجراءات في هذا المثال؟","target":"عضو في البرلمان يسأل وزيرًا عن تكلفة طريق. كيف تُفحص الإجابة؟","options":["اطلب تفاصيل المشروع والتمويل","راجع التقرير والمستندات","قارن الإجابة بالوقائع واطرح أسئلة متابعة","ليس من الضروري ترتيب الإجراءات مطلقًا"],"answerIndex":0,"explanation":"الترتيب في هذا المثال: اطلب تفاصيل المشروع والتمويل ← راجع التقرير والمستندات ← قارن الإجابة بالوقائع واطرح أسئلة متابعة. الرقابة الجيدة تقارن الأدلة دون افتراض مسبق أن رد الوزير أو المعارض صحيح."},{"kind":"choice","prompt":"ما الإجراء الذي يلي «اطلب تفاصيل المشروع والتمويل» مباشرة؟","target":"عضو في البرلمان يسأل وزيرًا عن تكلفة طريق. كيف تُفحص الإجابة؟","options":["اطلب تفاصيل المشروع والتمويل","راجع التقرير والمستندات","قارن الإجابة بالوقائع واطرح أسئلة متابعة","ليس من الضروري ترتيب الإجراءات مطلقًا"],"answerIndex":1,"explanation":"الترتيب في هذا المثال: اطلب تفاصيل المشروع والتمويل ← راجع التقرير والمستندات ← قارن الإجابة بالوقائع واطرح أسئلة متابعة. الرقابة الجيدة تقارن الأدلة دون افتراض مسبق أن رد الوزير أو المعارض صحيح."},{"kind":"choice","prompt":"ما الإجراء الأخير في هذا التسلسل؟","target":"عضو في البرلمان يسأل وزيرًا عن تكلفة طريق. كيف تُفحص الإجابة؟","options":["اطلب تفاصيل المشروع والتمويل","راجع التقرير والمستندات","قارن الإجابة بالوقائع واطرح أسئلة متابعة","ليس من الضروري ترتيب الإجراءات مطلقًا"],"answerIndex":2,"explanation":"الترتيب في هذا المثال: اطلب تفاصيل المشروع والتمويل ← راجع التقرير والمستندات ← قارن الإجابة بالوقائع واطرح أسئلة متابعة. الرقابة الجيدة تقارن الأدلة دون افتراض مسبق أن رد الوزير أو المعارض صحيح."}]},{"slug":"political-systems","index":10,"title":"السلطات أثناء الأزمات","model":"elections","activity":{"kind":"paths","title":"إدارة كارثة طارئة","story":"حدثت فيضانات واحتاجت السلطات لإجراءات مؤقتة.","question":"اختر ضمانة وراقب ما تضيفه.","choices":[["مهلة زمنية","تحدد متى تراجع الإجراءات الاستثنائية."],["رقابة مؤسسية","تراجع مدى الالتزام بالقانون والهدف."],["حق مراجعة القرار","يسمح بفحص التدابير المؤثرة في الحقوق."]],"explain":"الطوارئ لا تلغي تلقائيًا جميع الحقوق أو القواعد؛ يلزم فحص سند كل إجراء وحدوده."},"oldBody":"قد تتطلب كارثة طبيعية قرارات عاجلة تحدد مدتها وجهات مراجعتها وسبل الاعتراض عليها.\n\nوالآن تخيّل الموقف التالي: حدثت فيضانات واحتاجت السلطات لإجراءات مؤقتة.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"قد تتطلب كارثة طبيعية قرارات عاجلة تحدد مدتها وجهات مراجعتها وسبل الاعتراض عليها.\n\nوالآن تخيّل الموقف التالي: حدثت فيضانات واحتاجت السلطات لإجراءات مؤقتة.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال مشروح للمقارنة: حدثت فيضانات واحتاجت السلطات لإجراءات مؤقتة. لا نختار موقفًا سياسيًا على أنه إجابة واحدة مفروضة؛ بل ننظر في أثر كل جانب: مهلة زمنية — تحدد متى تراجع الإجراءات الاستثنائية.؛ رقابة مؤسسية — تراجع مدى الالتزام بالقانون والهدف.؛ حق مراجعة القرار — يسمح بفحص التدابير المؤثرة في الحقوق.. الطوارئ لا تلغي تلقائيًا جميع الحقوق أو القواعد؛ يلزم فحص سند كل إجراء وحدوده.","questions":[{"kind":"choice","prompt":"أي تفسير يطابق جانب «مهلة زمنية» في موقف «إدارة كارثة طارئة»؟","target":"حدثت فيضانات واحتاجت السلطات لإجراءات مؤقتة.","options":["تحدد متى تراجع الإجراءات الاستثنائية.","تراجع مدى الالتزام بالقانون والهدف.","يسمح بفحص التدابير المؤثرة في الحقوق.","لا يمكن أن يتأثر هذا الجانب بأي تغيير"],"answerIndex":0,"explanation":"في هذا الجانب: تحدد متى تراجع الإجراءات الاستثنائية. الطوارئ لا تلغي تلقائيًا جميع الحقوق أو القواعد؛ يلزم فحص سند كل إجراء وحدوده."},{"kind":"choice","prompt":"أي تفسير يطابق جانب «رقابة مؤسسية» في موقف «إدارة كارثة طارئة»؟","target":"حدثت فيضانات واحتاجت السلطات لإجراءات مؤقتة.","options":["تحدد متى تراجع الإجراءات الاستثنائية.","تراجع مدى الالتزام بالقانون والهدف.","يسمح بفحص التدابير المؤثرة في الحقوق.","لا يمكن أن يتأثر هذا الجانب بأي تغيير"],"answerIndex":1,"explanation":"في هذا الجانب: تراجع مدى الالتزام بالقانون والهدف. الطوارئ لا تلغي تلقائيًا جميع الحقوق أو القواعد؛ يلزم فحص سند كل إجراء وحدوده."},{"kind":"choice","prompt":"أي تفسير يطابق جانب «حق مراجعة القرار» في موقف «إدارة كارثة طارئة»؟","target":"حدثت فيضانات واحتاجت السلطات لإجراءات مؤقتة.","options":["تحدد متى تراجع الإجراءات الاستثنائية.","تراجع مدى الالتزام بالقانون والهدف.","يسمح بفحص التدابير المؤثرة في الحقوق.","لا يمكن أن يتأثر هذا الجانب بأي تغيير"],"answerIndex":2,"explanation":"في هذا الجانب: يسمح بفحص التدابير المؤثرة في الحقوق. الطوارئ لا تلغي تلقائيًا جميع الحقوق أو القواعد؛ يلزم فحص سند كل إجراء وحدوده."}]},{"slug":"political-systems","index":11,"title":"ورشة تصميم نظام حكم","model":"elections","activity":{"kind":"paths","title":"تصميم دولة افتراضية","story":"ستبني مؤسسات تحكم دولة افتراضية.","question":"راجع وظيفة كل عنصر قبل اعتماده.","choices":[["مجلس تشريعي","يناقش القوانين ويراقب ضمن صلاحياته."],["حكومة تنفيذية","تدير الخدمات وتطبق القانون."],["قضاء مستقل وظيفيًا","يفصل في النزاعات وفق القواعد والضمانات."]],"explain":"لا يوجد قالب واحد يناسب كل مجتمع؛ هذه أدوار مؤسسية وليست شهادة تفوق لنظام سياسي."},"oldBody":"صمم برلمانًا وحكومة وقضاءً وحدد ما يحدث إذا اختلفت مؤسستان حول قرار عام.\n\nوالآن تخيّل الموقف التالي: ستبني مؤسسات تحكم دولة افتراضية.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"صمم برلمانًا وحكومة وقضاءً وحدد ما يحدث إذا اختلفت مؤسستان حول قرار عام.\n\nوالآن تخيّل الموقف التالي: ستبني مؤسسات تحكم دولة افتراضية.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال مشروح للمقارنة: ستبني مؤسسات تحكم دولة افتراضية. لا نختار موقفًا سياسيًا على أنه إجابة واحدة مفروضة؛ بل ننظر في أثر كل جانب: مجلس تشريعي — يناقش القوانين ويراقب ضمن صلاحياته.؛ حكومة تنفيذية — تدير الخدمات وتطبق القانون.؛ قضاء مستقل وظيفيًا — يفصل في النزاعات وفق القواعد والضمانات.. لا يوجد قالب واحد يناسب كل مجتمع؛ هذه أدوار مؤسسية وليست شهادة تفوق لنظام سياسي.","questions":[{"kind":"choice","prompt":"أي تفسير يطابق جانب «مجلس تشريعي» في موقف «تصميم دولة افتراضية»؟","target":"ستبني مؤسسات تحكم دولة افتراضية.","options":["يناقش القوانين ويراقب ضمن صلاحياته.","تدير الخدمات وتطبق القانون.","يفصل في النزاعات وفق القواعد والضمانات.","لا يمكن أن يتأثر هذا الجانب بأي تغيير"],"answerIndex":0,"explanation":"في هذا الجانب: يناقش القوانين ويراقب ضمن صلاحياته. لا يوجد قالب واحد يناسب كل مجتمع؛ هذه أدوار مؤسسية وليست شهادة تفوق لنظام سياسي."},{"kind":"choice","prompt":"أي تفسير يطابق جانب «حكومة تنفيذية» في موقف «تصميم دولة افتراضية»؟","target":"ستبني مؤسسات تحكم دولة افتراضية.","options":["يناقش القوانين ويراقب ضمن صلاحياته.","تدير الخدمات وتطبق القانون.","يفصل في النزاعات وفق القواعد والضمانات.","لا يمكن أن يتأثر هذا الجانب بأي تغيير"],"answerIndex":1,"explanation":"في هذا الجانب: تدير الخدمات وتطبق القانون. لا يوجد قالب واحد يناسب كل مجتمع؛ هذه أدوار مؤسسية وليست شهادة تفوق لنظام سياسي."},{"kind":"choice","prompt":"أي تفسير يطابق جانب «قضاء مستقل وظيفيًا» في موقف «تصميم دولة افتراضية»؟","target":"ستبني مؤسسات تحكم دولة افتراضية.","options":["يناقش القوانين ويراقب ضمن صلاحياته.","تدير الخدمات وتطبق القانون.","يفصل في النزاعات وفق القواعد والضمانات.","لا يمكن أن يتأثر هذا الجانب بأي تغيير"],"answerIndex":2,"explanation":"في هذا الجانب: يفصل في النزاعات وفق القواعد والضمانات. لا يوجد قالب واحد يناسب كل مجتمع؛ هذه أدوار مؤسسية وليست شهادة تفوق لنظام سياسي."}]},{"slug":"economics-basics","index":0,"title":"الندرة والاختيار","model":"market","activity":{"kind":"paths","title":"قطعة أرض واحدة","story":"مدينة تملك قطعة أرض تصلح لمدرسة أو مستوصف أو حديقة.","question":"راجع ما الذي يتغير مع كل استخدام.","choices":[["مدرسة","قد تزيد السعة التعليمية لكنها تستخدم الأرض المتاحة."],["مستوصف","قد يحسن الوصول للرعاية، ويتطلب تشغيلًا وتمويلًا."],["حديقة","توفر مساحة عامة لكنها تؤجل استخدام الأرض للبدائل الأخرى."]],"explain":"الندرة هي قيد الموارد؛ المفاضلة تتطلب إعلان الهدف والاحتياجات والبدائل."},"oldBody":"إذا امتلكت مدينة قطعة أرض واحدة فقد تختار إنشاء مدرسة أو حديقة أو مركزًا صحيًا ولا تنفذ كل الخيارات في المكان نفسه.\n\nوالآن تخيّل الموقف التالي: مدينة تملك قطعة أرض تصلح لمدرسة أو مستوصف أو حديقة.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"إذا امتلكت مدينة قطعة أرض واحدة فقد تختار إنشاء مدرسة أو حديقة أو مركزًا صحيًا ولا تنفذ كل الخيارات في المكان نفسه.\n\nوالآن تخيّل الموقف التالي: مدينة تملك قطعة أرض تصلح لمدرسة أو مستوصف أو حديقة.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال مشروح للمقارنة: مدينة تملك قطعة أرض تصلح لمدرسة أو مستوصف أو حديقة. لا نختار موقفًا سياسيًا على أنه إجابة واحدة مفروضة؛ بل ننظر في أثر كل جانب: مدرسة — قد تزيد السعة التعليمية لكنها تستخدم الأرض المتاحة.؛ مستوصف — قد يحسن الوصول للرعاية، ويتطلب تشغيلًا وتمويلًا.؛ حديقة — توفر مساحة عامة لكنها تؤجل استخدام الأرض للبدائل الأخرى.. الندرة هي قيد الموارد؛ المفاضلة تتطلب إعلان الهدف والاحتياجات والبدائل.","questions":[{"kind":"choice","prompt":"أي تفسير يطابق جانب «مدرسة» في موقف «قطعة أرض واحدة»؟","target":"مدينة تملك قطعة أرض تصلح لمدرسة أو مستوصف أو حديقة.","options":["قد تزيد السعة التعليمية لكنها تستخدم الأرض المتاحة.","قد يحسن الوصول للرعاية، ويتطلب تشغيلًا وتمويلًا.","توفر مساحة عامة لكنها تؤجل استخدام الأرض للبدائل الأخرى.","لا يمكن أن يتأثر هذا الجانب بأي تغيير"],"answerIndex":0,"explanation":"في هذا الجانب: قد تزيد السعة التعليمية لكنها تستخدم الأرض المتاحة. الندرة هي قيد الموارد؛ المفاضلة تتطلب إعلان الهدف والاحتياجات والبدائل."},{"kind":"choice","prompt":"أي تفسير يطابق جانب «مستوصف» في موقف «قطعة أرض واحدة»؟","target":"مدينة تملك قطعة أرض تصلح لمدرسة أو مستوصف أو حديقة.","options":["قد تزيد السعة التعليمية لكنها تستخدم الأرض المتاحة.","قد يحسن الوصول للرعاية، ويتطلب تشغيلًا وتمويلًا.","توفر مساحة عامة لكنها تؤجل استخدام الأرض للبدائل الأخرى.","لا يمكن أن يتأثر هذا الجانب بأي تغيير"],"answerIndex":1,"explanation":"في هذا الجانب: قد يحسن الوصول للرعاية، ويتطلب تشغيلًا وتمويلًا. الندرة هي قيد الموارد؛ المفاضلة تتطلب إعلان الهدف والاحتياجات والبدائل."},{"kind":"choice","prompt":"أي تفسير يطابق جانب «حديقة» في موقف «قطعة أرض واحدة»؟","target":"مدينة تملك قطعة أرض تصلح لمدرسة أو مستوصف أو حديقة.","options":["قد تزيد السعة التعليمية لكنها تستخدم الأرض المتاحة.","قد يحسن الوصول للرعاية، ويتطلب تشغيلًا وتمويلًا.","توفر مساحة عامة لكنها تؤجل استخدام الأرض للبدائل الأخرى.","لا يمكن أن يتأثر هذا الجانب بأي تغيير"],"answerIndex":2,"explanation":"في هذا الجانب: توفر مساحة عامة لكنها تؤجل استخدام الأرض للبدائل الأخرى. الندرة هي قيد الموارد؛ المفاضلة تتطلب إعلان الهدف والاحتياجات والبدائل."}]},{"slug":"economics-basics","index":1,"title":"تكلفة الفرصة البديلة","model":"market","activity":{"kind":"numbers","title":"ثمن ساعتين من وقتك","story":"يمكنك العمل ساعتين بأجر أو الدراسة بدلًا من العمل.","question":"غير عدد الساعات والأجر واحسب الدخل الذي تتخلى عنه.","formula":"opportunity","x":{"label":"عدد الساعات","min":1,"max":8,"step":1,"initial":2,"unit":"ساعة"},"y":{"label":"أجر الساعة","min":5,"max":35,"step":5,"initial":15,"unit":"وحدة"},"explain":"هذه تكلفة نقدية للبديل المتروك وليست القيمة الكاملة للتعلم أو الوقت."},"oldBody":"إذا درست ساعتين بدل العمل المأجور فإن الأجر الذي كان ممكنًا كسبه جزء من تكلفة الفرصة.\n\nوالآن تخيّل الموقف التالي: يمكنك العمل ساعتين بأجر أو الدراسة بدلًا من العمل.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"إذا درست ساعتين بدل العمل المأجور فإن الأجر الذي كان ممكنًا كسبه جزء من تكلفة الفرصة.\n\nوالآن تخيّل الموقف التالي: يمكنك العمل ساعتين بأجر أو الدراسة بدلًا من العمل.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال محلول بالأرقام: يمكنك العمل ساعتين بأجر أو الدراسة بدلًا من العمل. نبدأ بقيم عدد الساعات = 2 ساعة، وأجر الساعة = 15 وحدة. يعطينا النموذج دخل البديل المتروك: 30 وحدة نقدية. بعد ذلك غيّر مدخلًا واحدًا وقارن النتيجة بدل توقعها من دون حساب. هذه تكلفة نقدية للبديل المتروك وليست القيمة الكاملة للتعلم أو الوقت.","questions":[{"kind":"choice","prompt":"عندما تصبح القيم «عدد الساعات: 1 ساعة، أجر الساعة: 5 وحدة»، فما قيمة «دخل البديل المتروك»؟","target":"يمكنك العمل ساعتين بأجر أو الدراسة بدلًا من العمل.","options":["5 وحدة نقدية","6 وحدة نقدية","4 وحدة نقدية","7 وحدة نقدية"],"answerIndex":0,"explanation":"نعوض القيم المعطاة في النموذج المبسط فنحصل على 5 وحدة نقدية. هذه تكلفة نقدية للبديل المتروك وليست القيمة الكاملة للتعلم أو الوقت."},{"kind":"choice","prompt":"عندما تصبح القيم «عدد الساعات: 8 ساعة، أجر الساعة: 35 وحدة»، فما قيمة «دخل البديل المتروك»؟","target":"يمكنك العمل ساعتين بأجر أو الدراسة بدلًا من العمل.","options":["280 وحدة نقدية","330 وحدة نقدية","230 وحدة نقدية","380 وحدة نقدية"],"answerIndex":0,"explanation":"نعوض القيم المعطاة في النموذج المبسط فنحصل على 280 وحدة نقدية. هذه تكلفة نقدية للبديل المتروك وليست القيمة الكاملة للتعلم أو الوقت."}]},{"slug":"economics-basics","index":2,"title":"العرض والطلب","model":"market","activity":{"kind":"numbers","title":"سوق الطماطم","story":"يريد مشترون وبائعون شراء وبيع سلعة بسعر يتحدد في نموذج خطي مبسط.","question":"غيّر الطلب أو العرض وشاهد سعر وكمية التوازن.","formula":"market","x":{"label":"تغير الطلب","min":-30,"max":30,"step":5,"initial":0,"unit":"وحدة"},"y":{"label":"تغير العرض","min":-30,"max":30,"step":5,"initial":0,"unit":"وحدة"},"explain":"الرسوم والتكاليف والمنافسة قد تغير النتيجة الحقيقية."},"oldBody":"عند ارتفاع طلب المستهلكين على سلعة مع ثبات العرض قد يرتفع سعر التوازن في نموذج سوق تنافسي مبسط.\n\nوالآن تخيّل الموقف التالي: يريد مشترون وبائعون شراء وبيع سلعة بسعر يتحدد في نموذج خطي مبسط.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"عند ارتفاع طلب المستهلكين على سلعة مع ثبات العرض قد يرتفع سعر التوازن في نموذج سوق تنافسي مبسط.\n\nوالآن تخيّل الموقف التالي: يريد مشترون وبائعون شراء وبيع سلعة بسعر يتحدد في نموذج خطي مبسط.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال محلول بالأرقام: يريد مشترون وبائعون شراء وبيع سلعة بسعر يتحدد في نموذج خطي مبسط. نبدأ بقيم تغير الطلب = 0 وحدة، وتغير العرض = 0 وحدة. يعطينا النموذج سعر التوازن في النموذج: 16.67 وحدة؛ الكمية عند التوازن: 53.33 وحدة. بعد ذلك غيّر مدخلًا واحدًا وقارن النتيجة بدل توقعها من دون حساب. الرسوم والتكاليف والمنافسة قد تغير النتيجة الحقيقية.","questions":[{"kind":"choice","prompt":"عندما تصبح القيم «تغير الطلب: -30 وحدة، تغير العرض: -30 وحدة»، فما قيمة «الكمية عند التوازن»؟","target":"يريد مشترون وبائعون شراء وبيع سلعة بسعر يتحدد في نموذج خطي مبسط.","options":["23.33 وحدة","27.33 وحدة","19.33 وحدة","31.33 وحدة"],"answerIndex":0,"explanation":"نعوض القيم المعطاة في النموذج المبسط فنحصل على 23.33 وحدة. الرسوم والتكاليف والمنافسة قد تغير النتيجة الحقيقية."},{"kind":"choice","prompt":"عندما تصبح القيم «تغير الطلب: 30 وحدة، تغير العرض: 30 وحدة»، فما قيمة «الكمية عند التوازن»؟","target":"يريد مشترون وبائعون شراء وبيع سلعة بسعر يتحدد في نموذج خطي مبسط.","options":["83.33 وحدة","98.33 وحدة","68.33 وحدة","113.33 وحدة"],"answerIndex":0,"explanation":"نعوض القيم المعطاة في النموذج المبسط فنحصل على 83.33 وحدة. الرسوم والتكاليف والمنافسة قد تغير النتيجة الحقيقية."}]},{"slug":"economics-basics","index":3,"title":"مرونة الطلب","model":"market","activity":{"kind":"numbers","title":"ما استجابة المشترين؟","story":"كان المتجر يبيع 100 وحدة عند سعر مرجعي، ثم تغير سعره وكميته المطلوبة.","question":"غيّر نسبتي السعر والكمية لحساب مرونة طلب تقريبية.","formula":"elasticity","x":{"label":"ارتفاع السعر","min":5,"max":30,"step":5,"initial":10,"unit":"%"},"y":{"label":"انخفاض الكمية","min":5,"max":60,"step":5,"initial":20,"unit":"%"},"explain":"نستخدم نسبة التغير المبسطة؛ تعتمد القيمة الفعلية على نقطة القياس وثبات العوامل الأخرى."},"oldBody":"إذا رفع متجر السعر بنسبة صغيرة وانخفضت المبيعات بنسبة أكبر يكون الطلب أكثر استجابة للسعر.\n\nوالآن تخيّل الموقف التالي: كان المتجر يبيع 100 وحدة عند سعر مرجعي، ثم تغير سعره وكميته المطلوبة.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"إذا رفع متجر السعر بنسبة صغيرة وانخفضت المبيعات بنسبة أكبر يكون الطلب أكثر استجابة للسعر.\n\nوالآن تخيّل الموقف التالي: كان المتجر يبيع 100 وحدة عند سعر مرجعي، ثم تغير سعره وكميته المطلوبة.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال محلول بالأرقام: كان المتجر يبيع 100 وحدة عند سعر مرجعي، ثم تغير سعره وكميته المطلوبة. نبدأ بقيم ارتفاع السعر = 10 %، وانخفاض الكمية = 20 %. يعطينا النموذج مرونة الطلب المطلقة التقريبية: 2 ؛ تغير السعر: 10 %؛ انخفاض الكمية: 20 %. بعد ذلك غيّر مدخلًا واحدًا وقارن النتيجة بدل توقعها من دون حساب. نستخدم نسبة التغير المبسطة؛ تعتمد القيمة الفعلية على نقطة القياس وثبات العوامل الأخرى.","questions":[{"kind":"choice","prompt":"عندما تصبح القيم «ارتفاع السعر: 5 %، انخفاض الكمية: 5 %»، فما قيمة «مرونة الطلب المطلقة التقريبية»؟","target":"كان المتجر يبيع 100 وحدة عند سعر مرجعي، ثم تغير سعره وكميته المطلوبة.","options":["1 ","2 ","0 ","3 "],"answerIndex":0,"explanation":"نعوض القيم المعطاة في النموذج المبسط فنحصل على 1 . نستخدم نسبة التغير المبسطة؛ تعتمد القيمة الفعلية على نقطة القياس وثبات العوامل الأخرى."},{"kind":"choice","prompt":"عندما تصبح القيم «ارتفاع السعر: 30 %، انخفاض الكمية: 60 %»، فما قيمة «تغير السعر»؟","target":"كان المتجر يبيع 100 وحدة عند سعر مرجعي، ثم تغير سعره وكميته المطلوبة.","options":["30 %","35 %","25 %","40 %"],"answerIndex":0,"explanation":"نعوض القيم المعطاة في النموذج المبسط فنحصل على 30 %. نستخدم نسبة التغير المبسطة؛ تعتمد القيمة الفعلية على نقطة القياس وثبات العوامل الأخرى."}]},{"slug":"economics-basics","index":4,"title":"المنافسة والاحتكار","model":"market","activity":{"kind":"paths","title":"سوق بمورد واحد","story":"خدمة محلية تقدمها شركة واحدة في مقابل دخول مورد جديد.","question":"افحص جوانب يمكن أن تتأثر بهيكل السوق.","choices":[["الخيارات","زيادة الموردين قد توفر بدائل أكثر للمستهلك."],["الأسعار","قد تتغير بحسب المنافسة والتكاليف واللوائح."],["جودة الخدمة","تحتاج مؤشرات مستقلة ولا تُستنتج من عدد الموردين فقط."]],"explain":"الحكم على الاحتكار أو المخالفة يحتاج تعريف السوق وتحليل السلوك لا عدد الشركات فقط."},"oldBody":"في سوق فيه مورد واحد لخدمة أساسية قد يجد المستهلك بدائل أقل مقارنة بسوق فيه عدة موردين.\n\nوالآن تخيّل الموقف التالي: خدمة محلية تقدمها شركة واحدة في مقابل دخول مورد جديد.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"في سوق فيه مورد واحد لخدمة أساسية قد يجد المستهلك بدائل أقل مقارنة بسوق فيه عدة موردين.\n\nوالآن تخيّل الموقف التالي: خدمة محلية تقدمها شركة واحدة في مقابل دخول مورد جديد.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال مشروح للمقارنة: خدمة محلية تقدمها شركة واحدة في مقابل دخول مورد جديد. لا نختار موقفًا سياسيًا على أنه إجابة واحدة مفروضة؛ بل ننظر في أثر كل جانب: الخيارات — زيادة الموردين قد توفر بدائل أكثر للمستهلك.؛ الأسعار — قد تتغير بحسب المنافسة والتكاليف واللوائح.؛ جودة الخدمة — تحتاج مؤشرات مستقلة ولا تُستنتج من عدد الموردين فقط.. الحكم على الاحتكار أو المخالفة يحتاج تعريف السوق وتحليل السلوك لا عدد الشركات فقط.","questions":[{"kind":"choice","prompt":"أي تفسير يطابق جانب «الخيارات» في موقف «سوق بمورد واحد»؟","target":"خدمة محلية تقدمها شركة واحدة في مقابل دخول مورد جديد.","options":["زيادة الموردين قد توفر بدائل أكثر للمستهلك.","قد تتغير بحسب المنافسة والتكاليف واللوائح.","تحتاج مؤشرات مستقلة ولا تُستنتج من عدد الموردين فقط.","لا يمكن أن يتأثر هذا الجانب بأي تغيير"],"answerIndex":0,"explanation":"في هذا الجانب: زيادة الموردين قد توفر بدائل أكثر للمستهلك. الحكم على الاحتكار أو المخالفة يحتاج تعريف السوق وتحليل السلوك لا عدد الشركات فقط."},{"kind":"choice","prompt":"أي تفسير يطابق جانب «الأسعار» في موقف «سوق بمورد واحد»؟","target":"خدمة محلية تقدمها شركة واحدة في مقابل دخول مورد جديد.","options":["زيادة الموردين قد توفر بدائل أكثر للمستهلك.","قد تتغير بحسب المنافسة والتكاليف واللوائح.","تحتاج مؤشرات مستقلة ولا تُستنتج من عدد الموردين فقط.","لا يمكن أن يتأثر هذا الجانب بأي تغيير"],"answerIndex":1,"explanation":"في هذا الجانب: قد تتغير بحسب المنافسة والتكاليف واللوائح. الحكم على الاحتكار أو المخالفة يحتاج تعريف السوق وتحليل السلوك لا عدد الشركات فقط."},{"kind":"choice","prompt":"أي تفسير يطابق جانب «جودة الخدمة» في موقف «سوق بمورد واحد»؟","target":"خدمة محلية تقدمها شركة واحدة في مقابل دخول مورد جديد.","options":["زيادة الموردين قد توفر بدائل أكثر للمستهلك.","قد تتغير بحسب المنافسة والتكاليف واللوائح.","تحتاج مؤشرات مستقلة ولا تُستنتج من عدد الموردين فقط.","لا يمكن أن يتأثر هذا الجانب بأي تغيير"],"answerIndex":2,"explanation":"في هذا الجانب: تحتاج مؤشرات مستقلة ولا تُستنتج من عدد الموردين فقط. الحكم على الاحتكار أو المخالفة يحتاج تعريف السوق وتحليل السلوك لا عدد الشركات فقط."}]},{"slug":"economics-basics","index":5,"title":"تكاليف الإنتاج","model":"market","activity":{"kind":"numbers","title":"تكلفة الخبز","story":"مخبز يدفع إيجارًا شهريًا ومكونات لكل رغيف.","question":"بدّل عدد الأرغفة وتكلفة المكونات لحساب تكلفة الوحدة.","formula":"cost","x":{"label":"عدد الأرغفة","min":100,"max":1000,"step":100,"initial":500,"unit":"رغيف"},"y":{"label":"مكونات لكل رغيف","min":1,"max":5,"step":1,"initial":2,"unit":"وحدة"},"explain":"إيجار ثابت افتراضي 1000 وحدة؛ لا يشمل المثال الطاقة والضرائب والعمل."},"oldBody":"يدفع مخبز إيجارًا ثابتًا ويشتري دقيقًا يزيد استهلاكه كلما ارتفع إنتاج الخبز.\n\nوالآن تخيّل الموقف التالي: مخبز يدفع إيجارًا شهريًا ومكونات لكل رغيف.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"يدفع مخبز إيجارًا ثابتًا ويشتري دقيقًا يزيد استهلاكه كلما ارتفع إنتاج الخبز.\n\nوالآن تخيّل الموقف التالي: مخبز يدفع إيجارًا شهريًا ومكونات لكل رغيف.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال محلول بالأرقام: مخبز يدفع إيجارًا شهريًا ومكونات لكل رغيف. نبدأ بقيم عدد الأرغفة = 500 رغيف، ومكونات لكل رغيف = 2 وحدة. يعطينا النموذج التكلفة الكلية: 2000 وحدة؛ تكلفة الرغيف: 4 وحدة. بعد ذلك غيّر مدخلًا واحدًا وقارن النتيجة بدل توقعها من دون حساب. إيجار ثابت افتراضي 1000 وحدة؛ لا يشمل المثال الطاقة والضرائب والعمل.","questions":[{"kind":"choice","prompt":"عندما تصبح القيم «عدد الأرغفة: 100 رغيف، مكونات لكل رغيف: 1 وحدة»، فما قيمة «التكلفة الكلية»؟","target":"مخبز يدفع إيجارًا شهريًا ومكونات لكل رغيف.","options":["1100 وحدة","1298 وحدة","902 وحدة","1496 وحدة"],"answerIndex":0,"explanation":"نعوض القيم المعطاة في النموذج المبسط فنحصل على 1100 وحدة. إيجار ثابت افتراضي 1000 وحدة؛ لا يشمل المثال الطاقة والضرائب والعمل."},{"kind":"choice","prompt":"عندما تصبح القيم «عدد الأرغفة: 1000 رغيف، مكونات لكل رغيف: 5 وحدة»، فما قيمة «التكلفة الكلية»؟","target":"مخبز يدفع إيجارًا شهريًا ومكونات لكل رغيف.","options":["6000 وحدة","7080 وحدة","4920 وحدة","8160 وحدة"],"answerIndex":0,"explanation":"نعوض القيم المعطاة في النموذج المبسط فنحصل على 6000 وحدة. إيجار ثابت افتراضي 1000 وحدة؛ لا يشمل المثال الطاقة والضرائب والعمل."}]},{"slug":"economics-basics","index":6,"title":"الإنتاجية والتخصص","model":"market","activity":{"kind":"numbers","title":"كم تنتج في الساعة؟","story":"فريق ينتج قطعًا خلال ساعات عمل محددة.","question":"غيّر الإنتاج وساعات العمل، واحسب إنتاجية الساعة.","formula":"productivity","x":{"label":"القطع المنتجة","min":40,"max":240,"step":20,"initial":100,"unit":"قطعة"},"y":{"label":"ساعات العمل","min":5,"max":20,"step":1,"initial":10,"unit":"ساعة"},"explain":"تحسن الإنتاجية المقاسة لا يعني تلقائيًا ارتفاع الأجور أو الجودة."},"oldBody":"إذا أنتج فريق 100 قطعة في 10 ساعات بدل 50 قطعة بنفس الوقت فقد تضاعفت إنتاجيته المقاسة.\n\nوالآن تخيّل الموقف التالي: فريق ينتج قطعًا خلال ساعات عمل محددة.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"إذا أنتج فريق 100 قطعة في 10 ساعات بدل 50 قطعة بنفس الوقت فقد تضاعفت إنتاجيته المقاسة.\n\nوالآن تخيّل الموقف التالي: فريق ينتج قطعًا خلال ساعات عمل محددة.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال محلول بالأرقام: فريق ينتج قطعًا خلال ساعات عمل محددة. نبدأ بقيم القطع المنتجة = 100 قطعة، وساعات العمل = 10 ساعة. يعطينا النموذج الإنتاج لكل ساعة: 10 قطعة/ساعة. بعد ذلك غيّر مدخلًا واحدًا وقارن النتيجة بدل توقعها من دون حساب. تحسن الإنتاجية المقاسة لا يعني تلقائيًا ارتفاع الأجور أو الجودة.","questions":[{"kind":"choice","prompt":"عندما تصبح القيم «القطع المنتجة: 40 قطعة، ساعات العمل: 5 ساعة»، فما قيمة «الإنتاج لكل ساعة»؟","target":"فريق ينتج قطعًا خلال ساعات عمل محددة.","options":["8 قطعة/ساعة","9 قطعة/ساعة","7 قطعة/ساعة","10 قطعة/ساعة"],"answerIndex":0,"explanation":"نعوض القيم المعطاة في النموذج المبسط فنحصل على 8 قطعة/ساعة. تحسن الإنتاجية المقاسة لا يعني تلقائيًا ارتفاع الأجور أو الجودة."},{"kind":"choice","prompt":"عندما تصبح القيم «القطع المنتجة: 240 قطعة، ساعات العمل: 20 ساعة»، فما قيمة «الإنتاج لكل ساعة»؟","target":"فريق ينتج قطعًا خلال ساعات عمل محددة.","options":["12 قطعة/ساعة","14 قطعة/ساعة","10 قطعة/ساعة","16 قطعة/ساعة"],"answerIndex":0,"explanation":"نعوض القيم المعطاة في النموذج المبسط فنحصل على 12 قطعة/ساعة. تحسن الإنتاجية المقاسة لا يعني تلقائيًا ارتفاع الأجور أو الجودة."}]},{"slug":"economics-basics","index":7,"title":"كيف تتشكل الأسعار؟","model":"market","activity":{"kind":"case","title":"ارتفع السعر فجأة","story":"ارتفع سعر سلعة بعد زيادة رسوم الشحن مع ثبات طلب المشترين.","question":"أي جانب تغيّر على الأرجح في هذا المثال؟","choices":["تكاليف العرض والنقل","عدد الكواكب","القانون الدستوري"],"explain":"قد تتحرك الأسعار بسبب تغير تكاليف الإنتاج أو النقل، وليس بسبب الطلب وحده.","correctIndex":0},"oldBody":"قد ترتفع أسعار سلعة بعد زيادة تكاليف النقل حتى لو لم يتغير عدد المشترين.\n\nوالآن تخيّل الموقف التالي: ارتفع سعر سلعة بعد زيادة رسوم الشحن مع ثبات طلب المشترين.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"قد ترتفع أسعار سلعة بعد زيادة تكاليف النقل حتى لو لم يتغير عدد المشترين.\n\nوالآن تخيّل الموقف التالي: ارتفع سعر سلعة بعد زيادة رسوم الشحن مع ثبات طلب المشترين.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال مشروح خطوة بخطوة: ارتفع سعر سلعة بعد زيادة رسوم الشحن مع ثبات طلب المشترين. نبدأ بتحديد السؤال: أي جانب تغيّر على الأرجح في هذا المثال؟ ننظر في الخيارات، ثم نبحث عن المعلومة التي يثبتها الواقع أو القانون. في هذا الموقف الإجابة الأدق هي «تكاليف العرض والنقل». والسبب: قد تتحرك الأسعار بسبب تغير تكاليف الإنتاج أو النقل، وليس بسبب الطلب وحده.","questions":[{"kind":"choice","prompt":"في حالة «ارتفع السعر فجأة»: أي جانب تغيّر على الأرجح في هذا المثال؟","target":"ارتفع سعر سلعة بعد زيادة رسوم الشحن مع ثبات طلب المشترين.","options":["تكاليف العرض والنقل","عدد الكواكب","القانون الدستوري","لا علاقة لتلك الخيارات بفهم الموقف"],"answerIndex":0,"explanation":"قد تتحرك الأسعار بسبب تغير تكاليف الإنتاج أو النقل، وليس بسبب الطلب وحده."},{"kind":"choice","prompt":"عندما ترتفع كلفة الشحن مع ثبات طلب المشترين، ما العلاقة التي تستحق الفحص؟","target":"ارتفع سعر سلعة بعد زيادة رسوم الشحن مع ثبات طلب المشترين.","options":["تأثير تكاليف العرض على الأسعار","انخفاض عدد المشترين دون أي دليل","زيادة المعروض بلا تغير في تكاليفه","اختفاء الحاجة إلى النقل من السوق"],"answerIndex":0,"explanation":"قد تتحرك الأسعار بسبب تغير تكاليف الإنتاج أو النقل، وليس بسبب الطلب وحده."}]},{"slug":"economics-basics","index":8,"title":"الناتج المحلي الإجمالي","model":"market","activity":{"kind":"numbers","title":"ناتج مصنعين","story":"دولة افتراضية تنتج خدمات وسلعًا نهائية في سنة واحدة.","question":"غيّر قيم المخرجات النهائية لترى مجموع الإنتاج قبل خصم أي مدخلات وسيطة.","formula":"gdp","x":{"label":"قيمة سلع نهائية","min":100,"max":1000,"step":100,"initial":500,"unit":"وحدة"},"y":{"label":"قيمة خدمات نهائية","min":100,"max":1000,"step":100,"initial":400,"unit":"وحدة"},"explain":"لا تكرر احتساب المدخل الوسيط إذا دخل في قيمة السلعة النهائية."},"oldBody":"تدخل قيمة خدمة صيانة جديدة في الناتج وفق الحسابات القومية، ولا تُجمع قيمة الوسيط مرة ثانية إذا احتسبت في المنتج النهائي.\n\nوالآن تخيّل الموقف التالي: دولة افتراضية تنتج خدمات وسلعًا نهائية في سنة واحدة.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"تدخل قيمة خدمة صيانة جديدة في الناتج وفق الحسابات القومية، ولا تُجمع قيمة الوسيط مرة ثانية إذا احتسبت في المنتج النهائي.\n\nوالآن تخيّل الموقف التالي: دولة افتراضية تنتج خدمات وسلعًا نهائية في سنة واحدة.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال محلول بالأرقام: دولة افتراضية تنتج خدمات وسلعًا نهائية في سنة واحدة. نبدأ بقيم قيمة سلع نهائية = 500 وحدة، وقيمة خدمات نهائية = 400 وحدة. يعطينا النموذج إجمالي السلع والخدمات النهائية: 900 وحدة. بعد ذلك غيّر مدخلًا واحدًا وقارن النتيجة بدل توقعها من دون حساب. لا تكرر احتساب المدخل الوسيط إذا دخل في قيمة السلعة النهائية.","questions":[{"kind":"choice","prompt":"عندما تصبح القيم «قيمة سلع نهائية: 100 وحدة، قيمة خدمات نهائية: 100 وحدة»، فما قيمة «إجمالي السلع والخدمات النهائية»؟","target":"دولة افتراضية تنتج خدمات وسلعًا نهائية في سنة واحدة.","options":["200 وحدة","236 وحدة","164 وحدة","272 وحدة"],"answerIndex":0,"explanation":"نعوض القيم المعطاة في النموذج المبسط فنحصل على 200 وحدة. لا تكرر احتساب المدخل الوسيط إذا دخل في قيمة السلعة النهائية."},{"kind":"choice","prompt":"عندما تصبح القيم «قيمة سلع نهائية: 1000 وحدة، قيمة خدمات نهائية: 1000 وحدة»، فما قيمة «إجمالي السلع والخدمات النهائية»؟","target":"دولة افتراضية تنتج خدمات وسلعًا نهائية في سنة واحدة.","options":["2000 وحدة","2360 وحدة","1640 وحدة","2720 وحدة"],"answerIndex":0,"explanation":"نعوض القيم المعطاة في النموذج المبسط فنحصل على 2000 وحدة. لا تكرر احتساب المدخل الوسيط إذا دخل في قيمة السلعة النهائية."}]},{"slug":"economics-basics","index":9,"title":"البطالة وسوق العمل","model":"market","activity":{"kind":"numbers","title":"من العاطل إحصائيًا؟","story":"مدينة لديها قوة عمل وعدد أشخاص يبحثون عن عمل ومتاحون له.","question":"غيّر قوة العمل وعدد الباحثين عن عمل واحسب معدل البطالة.","formula":"unemployment","x":{"label":"قوة العمل","min":100,"max":1000,"step":100,"initial":500,"unit":"شخص"},"y":{"label":"العاطلون الباحثون","min":0,"max":100,"step":10,"initial":50,"unit":"شخص"},"explain":"من لا يبحث عن عمل لا يدخل عادة في البسط؛ ولا تكفي البطالة وحدها لفهم سوق العمل."},"oldBody":"قد يكون شخص لا يعمل ولا يبحث عن وظيفة خارج قوة العمل في الإحصاء، لا ضمن العاطلين.\n\nوالآن تخيّل الموقف التالي: مدينة لديها قوة عمل وعدد أشخاص يبحثون عن عمل ومتاحون له.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"قد يكون شخص لا يعمل ولا يبحث عن وظيفة خارج قوة العمل في الإحصاء، لا ضمن العاطلين.\n\nوالآن تخيّل الموقف التالي: مدينة لديها قوة عمل وعدد أشخاص يبحثون عن عمل ومتاحون له.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال محلول بالأرقام: مدينة لديها قوة عمل وعدد أشخاص يبحثون عن عمل ومتاحون له. نبدأ بقيم قوة العمل = 500 شخص، والعاطلون الباحثون = 50 شخص. يعطينا النموذج معدل البطالة: 10 %. بعد ذلك غيّر مدخلًا واحدًا وقارن النتيجة بدل توقعها من دون حساب. من لا يبحث عن عمل لا يدخل عادة في البسط؛ ولا تكفي البطالة وحدها لفهم سوق العمل.","questions":[{"kind":"choice","prompt":"عندما تصبح القيم «قوة العمل: 100 شخص، العاطلون الباحثون: 0 شخص»، فما قيمة «معدل البطالة»؟","target":"مدينة لديها قوة عمل وعدد أشخاص يبحثون عن عمل ومتاحون له.","options":["0 %","1 %","-1 %","2 %"],"answerIndex":0,"explanation":"نعوض القيم المعطاة في النموذج المبسط فنحصل على 0 %. من لا يبحث عن عمل لا يدخل عادة في البسط؛ ولا تكفي البطالة وحدها لفهم سوق العمل."},{"kind":"choice","prompt":"عندما تصبح القيم «قوة العمل: 1000 شخص، العاطلون الباحثون: 50 شخص»، فما قيمة «معدل البطالة»؟","target":"مدينة لديها قوة عمل وعدد أشخاص يبحثون عن عمل ومتاحون له.","options":["5 %","6 %","4 %","7 %"],"answerIndex":0,"explanation":"نعوض القيم المعطاة في النموذج المبسط فنحصل على 5 %. من لا يبحث عن عمل لا يدخل عادة في البسط؛ ولا تكفي البطالة وحدها لفهم سوق العمل."}]},{"slug":"economics-basics","index":10,"title":"النمو والدورات الاقتصادية","model":"market","activity":{"kind":"numbers","title":"هل الإنتاج زاد حقًا؟","story":"تغير الإنتاج الحقيقي من سنة إلى التالية، بعد فصل أثر الأسعار.","question":"قارن الناتج الحقيقي في عامين لتحسب النمو المئوي.","formula":"growth","x":{"label":"الناتج في العام الأول","min":100,"max":1000,"step":100,"initial":500,"unit":"وحدة"},"y":{"label":"الناتج في العام الثاني","min":100,"max":1200,"step":100,"initial":600,"unit":"وحدة"},"explain":"هذا حساب تغير في الناتج الحقيقي، لا قياس لتوزيع مكاسب النمو."},"oldBody":"عندما يرتفع إنتاج الاقتصاد بعد تعديل أثر الأسعار قد يعكس نموًا حقيقيًا لا مجرد تضخم اسمي.\n\nوالآن تخيّل الموقف التالي: تغير الإنتاج الحقيقي من سنة إلى التالية، بعد فصل أثر الأسعار.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"عندما يرتفع إنتاج الاقتصاد بعد تعديل أثر الأسعار قد يعكس نموًا حقيقيًا لا مجرد تضخم اسمي.\n\nوالآن تخيّل الموقف التالي: تغير الإنتاج الحقيقي من سنة إلى التالية، بعد فصل أثر الأسعار.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال محلول بالأرقام: تغير الإنتاج الحقيقي من سنة إلى التالية، بعد فصل أثر الأسعار. نبدأ بقيم الناتج في العام الأول = 500 وحدة، والناتج في العام الثاني = 600 وحدة. يعطينا النموذج التغير الحقيقي: 20 %. بعد ذلك غيّر مدخلًا واحدًا وقارن النتيجة بدل توقعها من دون حساب. هذا حساب تغير في الناتج الحقيقي، لا قياس لتوزيع مكاسب النمو.","questions":[{"kind":"choice","prompt":"عندما تصبح القيم «الناتج في العام الأول: 100 وحدة، الناتج في العام الثاني: 100 وحدة»، فما قيمة «التغير الحقيقي»؟","target":"تغير الإنتاج الحقيقي من سنة إلى التالية، بعد فصل أثر الأسعار.","options":["0 %","1 %","-1 %","2 %"],"answerIndex":0,"explanation":"نعوض القيم المعطاة في النموذج المبسط فنحصل على 0 %. هذا حساب تغير في الناتج الحقيقي، لا قياس لتوزيع مكاسب النمو."},{"kind":"choice","prompt":"عندما تصبح القيم «الناتج في العام الأول: 1000 وحدة، الناتج في العام الثاني: 600 وحدة»، فما قيمة «التغير الحقيقي»؟","target":"تغير الإنتاج الحقيقي من سنة إلى التالية، بعد فصل أثر الأسعار.","options":["-40 %","-33 %","-47 %","-26 %"],"answerIndex":0,"explanation":"نعوض القيم المعطاة في النموذج المبسط فنحصل على -40 %. هذا حساب تغير في الناتج الحقيقي، لا قياس لتوزيع مكاسب النمو."}]},{"slug":"economics-basics","index":11,"title":"مشروع إدارة سوق مدينة","model":"market","activity":{"kind":"numbers","title":"أزمة في سوق الغذاء","story":"زادت مشتريات السكان وتأخرت الشاحنات التي تحمل السلع.","question":"جرّب صدمة الطلب والعرض معًا؛ راقب السعر والكمية.","formula":"market","x":{"label":"تغير الطلب","min":-30,"max":30,"step":5,"initial":15,"unit":"وحدة"},"y":{"label":"تغير العرض","min":-30,"max":30,"step":5,"initial":-15,"unit":"وحدة"},"explain":"النموذج افتراضي خطي؛ لا يعد توقعًا للأسعار الحقيقية."},"oldBody":"إذا حدث نقص في سلعة غيّر افتراضات العرض والطلب وافحص السعر والكمية ثم ناقش الخيارات.\n\nوالآن تخيّل الموقف التالي: زادت مشتريات السكان وتأخرت الشاحنات التي تحمل السلع.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"إذا حدث نقص في سلعة غيّر افتراضات العرض والطلب وافحص السعر والكمية ثم ناقش الخيارات.\n\nوالآن تخيّل الموقف التالي: زادت مشتريات السكان وتأخرت الشاحنات التي تحمل السلع.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال محلول بالأرقام: زادت مشتريات السكان وتأخرت الشاحنات التي تحمل السلع. نبدأ بقيم تغير الطلب = 15 وحدة، وتغير العرض = -15 وحدة. يعطينا النموذج سعر التوازن في النموذج: 21.67 وحدة؛ الكمية عند التوازن: 48.33 وحدة. بعد ذلك غيّر مدخلًا واحدًا وقارن النتيجة بدل توقعها من دون حساب. النموذج افتراضي خطي؛ لا يعد توقعًا للأسعار الحقيقية.","questions":[{"kind":"choice","prompt":"عندما تصبح القيم «تغير الطلب: -30 وحدة، تغير العرض: -30 وحدة»، فما قيمة «سعر التوازن في النموذج»؟","target":"زادت مشتريات السكان وتأخرت الشاحنات التي تحمل السلع.","options":["16.67 وحدة","19.67 وحدة","13.67 وحدة","22.67 وحدة"],"answerIndex":0,"explanation":"نعوض القيم المعطاة في النموذج المبسط فنحصل على 16.67 وحدة. النموذج افتراضي خطي؛ لا يعد توقعًا للأسعار الحقيقية."},{"kind":"choice","prompt":"عندما تصبح القيم «تغير الطلب: 30 وحدة، تغير العرض: -15 وحدة»، فما قيمة «سعر التوازن في النموذج»؟","target":"زادت مشتريات السكان وتأخرت الشاحنات التي تحمل السلع.","options":["24.17 وحدة","28.17 وحدة","20.17 وحدة","32.17 وحدة"],"answerIndex":0,"explanation":"نعوض القيم المعطاة في النموذج المبسط فنحصل على 24.17 وحدة. النموذج افتراضي خطي؛ لا يعد توقعًا للأسعار الحقيقية."}]},{"slug":"money-banks-inflation","index":0,"title":"وظائف النقود","model":"monetary","activity":{"kind":"case","title":"شراء دون مقايضة","story":"تملك خبزًا وتريد كتابًا، والبائع لا يريد الخبز مقابل كتابه.","question":"ما فائدة النقود في هذا الموقف؟","choices":["تعمل وسيطًا للتبادل دون تطابق مباشر للاحتياجات","تلغي جميع الأسعار","تجعل السلع مجانية"],"explain":"النقود تفصل عمليتي البيع والشراء ولا تضمن ثبات القوة الشرائية.","correctIndex":0},"oldBody":"يسهل شراء الخبز بالنقود بدل مبادلته مباشرةً بسلعة يحتاجها الخباز في اللحظة نفسها.\n\nوالآن تخيّل الموقف التالي: تملك خبزًا وتريد كتابًا، والبائع لا يريد الخبز مقابل كتابه.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"يسهل شراء الخبز بالنقود بدل مبادلته مباشرةً بسلعة يحتاجها الخباز في اللحظة نفسها.\n\nوالآن تخيّل الموقف التالي: تملك خبزًا وتريد كتابًا، والبائع لا يريد الخبز مقابل كتابه.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال مشروح خطوة بخطوة: تملك خبزًا وتريد كتابًا، والبائع لا يريد الخبز مقابل كتابه. نبدأ بتحديد السؤال: ما فائدة النقود في هذا الموقف؟ ننظر في الخيارات، ثم نبحث عن المعلومة التي يثبتها الواقع أو القانون. في هذا الموقف الإجابة الأدق هي «تعمل وسيطًا للتبادل دون تطابق مباشر للاحتياجات». والسبب: النقود تفصل عمليتي البيع والشراء ولا تضمن ثبات القوة الشرائية.","questions":[{"kind":"choice","prompt":"في حالة «شراء دون مقايضة»: ما فائدة النقود في هذا الموقف؟","target":"تملك خبزًا وتريد كتابًا، والبائع لا يريد الخبز مقابل كتابه.","options":["تعمل وسيطًا للتبادل دون تطابق مباشر للاحتياجات","تلغي جميع الأسعار","تجعل السلع مجانية","لا علاقة لتلك الخيارات بفهم الموقف"],"answerIndex":0,"explanation":"النقود تفصل عمليتي البيع والشراء ولا تضمن ثبات القوة الشرائية."},{"kind":"choice","prompt":"كيف تساعد النقود شخصًا يملك خبزًا ويريد كتابًا؟","target":"تملك خبزًا وتريد كتابًا، والبائع لا يريد الخبز مقابل كتابه.","options":["تتيح بيع الخبز ثم شراء الكتاب دون تطابق مباشر في المقايضة","تجعل الكتب مجانية لأي شخص","تفرض على البائع قبول الخبز مقابل الكتاب","تلغي كل تكاليف التبادل"],"answerIndex":0,"explanation":"النقود تفصل عمليتي البيع والشراء ولا تضمن ثبات القوة الشرائية."}]},{"slug":"money-banks-inflation","index":1,"title":"المصارف والودائع","model":"monetary","activity":{"kind":"steps","title":"كيف تصل الحوالة؟","story":"أودعت ليلى مالًا في حسابها وترغب في دفع فاتورة.","steps":["تتحقق من رصيد الحساب والبيانات","تطلب تحويلًا أو دفعًا مصرفيًا","تراجع إيصال العملية ونتيجتها"],"explain":"التحويل الإلكتروني يعتمد على بنية دفع وشروط البنك ولا يعني نقل أوراق نقدية يدويًا."},"oldBody":"يودع عميل راتبه في حساب ثم يدفع منه الفواتير عبر تحويل مصرفي إلكتروني.\n\nوالآن تخيّل الموقف التالي: أودعت ليلى مالًا في حسابها وترغب في دفع فاتورة.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","newBody":"يودع عميل راتبه في حساب ثم يدفع منه الفواتير عبر تحويل مصرفي إلكتروني.\n\nوالآن تخيّل الموقف التالي: أودعت ليلى مالًا في حسابها وترغب في دفع فاتورة.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.\n\nمثال محلول: أودعت ليلى مالًا في حسابها وترغب في دفع فاتورة. الترتيب هنا هو: تتحقق من رصيد الحساب والبيانات ← تطلب تحويلًا أو دفعًا مصرفيًا ← تراجع إيصال العملية ونتيجتها. افهم ما تحتاجه كل خطوة من سابقتها، ولماذا يختلف القرار النهائي لو بدأنا بالنتيجة بدل دراسة المعطيات. التحويل الإلكتروني يعتمد على بنية دفع وشروط البنك ولا يعني نقل أوراق نقدية يدويًا.","questions":[{"kind":"choice","prompt":"أي إجراء يسبق بقية الإجراءات في هذا المثال؟","target":"أودعت ليلى مالًا في حسابها وترغب في دفع فاتورة.","options":["تتحقق من رصيد الحساب والبيانات","تطلب تحويلًا أو دفعًا مصرفيًا","تراجع إيصال العملية ونتيجتها","ليس من الضروري ترتيب الإجراءات مطلقًا"],"answerIndex":0,"explanation":"الترتيب في هذا المثال: تتحقق من رصيد الحساب والبيانات ← تطلب تحويلًا أو دفعًا مصرفيًا ← تراجع إيصال العملية ونتيجتها. التحويل الإلكتروني يعتمد على بنية دفع وشروط البنك ولا يعني نقل أوراق نقدية يدويًا."},{"kind":"choice","prompt":"ما الإجراء الذي يلي «تتحقق من رصيد الحساب والبيانات» مباشرة؟","target":"أودعت ليلى مالًا في حسابها وترغب في دفع فاتورة.","options":["تتحقق من رصيد الحساب والبيانات","تطلب تحويلًا أو دفعًا مصرفيًا","تراجع إيصال العملية ونتيجتها","ليس من الضروري ترتيب الإجراءات مطلقًا"],"answerIndex":1,"explanation":"الترتيب في هذا المثال: تتحقق من رصيد الحساب والبيانات ← تطلب تحويلًا أو دفعًا مصرفيًا ← تراجع إيصال العملية ونتيجتها. التحويل الإلكتروني يعتمد على بنية دفع وشروط البنك ولا يعني نقل أوراق نقدية يدويًا."},{"kind":"choice","prompt":"ما الإجراء الأخير في هذا التسلسل؟","target":"أودعت ليلى مالًا في حسابها وترغب في دفع فاتورة.","options":["تتحقق من رصيد الحساب والبيانات","تطلب تحويلًا أو دفعًا مصرفيًا","تراجع إيصال العملية ونتيجتها","ليس من الضروري ترتيب الإجراءات مطلقًا"],"answerIndex":2,"explanation":"الترتيب في هذا المثال: تتحقق من رصيد الحساب والبيانات ← تطلب تحويلًا أو دفعًا مصرفيًا ← تراجع إيصال العملية ونتيجتها. التحويل الإلكتروني 