 LOOP
  UPDATE public.school_editor_stages st SET
   published=case
    when st.published->'lessons'->1->>'body'=item->>'oldBody'
    then jsonb_set(
      jsonb_set(st.published,'{lab,activity}',item->'activity',true),
      '{lessons,1,body}',to_jsonb(item->>'newBody'),true)
    else jsonb_set(st.published,'{lab,activity}',item->'activity',true) end,
   draft=case when st.draft->'lab'=st.published->'lab' then
     case when st.draft->'lessons'->1->>'body'=item->>'oldBody'
      then jsonb_set(jsonb_set(st.draft,'{lab,activity}',item->'activity',true),
       '{lessons,1,body}',to_jsonb(item->>'newBody'),true)
      else jsonb_set(st.draft,'{lab,activity}',item->'activity',true) end
     else st.draft end
  WHERE st.course_slug=item->>'slug'
    AND st.stage_index=(item->>'index')::integer
    AND st.published->>'title'=item->>'title'
    AND st.published->'lab'->>'kind'='civic'
    AND st.published->'lab'->>'model'=item->>'model'
    AND st.published->'lab'->'activity' IS NULL;

  FOR q IN SELECT value FROM jsonb_array_elements(item->'questions')
  LOOP
   INSERT INTO public.school_editor_questions
    (course_slug,stage_index,draft,published,version,published_version)
   SELECT item->>'slug',(item->>'index')::integer,q,q,1,1
   WHERE EXISTS (
    SELECT 1 FROM public.school_editor_stages st
    WHERE st.course_slug=item->>'slug'
      AND st.stage_index=(item->>'index')::integer
      AND st.published->'lab'->'activity'=item->'activity'
   )
   AND NOT EXISTS (
    SELECT 1 FROM public.school_editor_questions previous
    WHERE previous.course_slug=item->>'slug'
      AND previous.stage_index=(item->>'index')::integer
      AND previous.published->>'prompt'=q->>'prompt'
   );
  END LOOP;
 END LOOP;
END
$school_phase2$;
